INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('sciences', 1, 'Quel est le satellite naturel de la Terre ?', 'La Lune', ARRAY['Phobos', 'Titan', 'Europe'], 'fr', true, 'La Lune est l''unique satellite naturel de la Terre, situé à environ 384 400 km.'),
('sciences', 1, 'Combien de couleurs y a-t-il dans un arc-en-ciel ?', '7', ARRAY['5', '6', '8'], 'fr', true, 'L''arc-en-ciel comporte 7 couleurs : rouge, orange, jaune, vert, bleu, indigo et violet.'),
('sciences', 1, 'Quel est le gaz que nous expirons principalement ?', 'Le dioxyde de carbone', ARRAY['L''oxygène', 'L''azote', 'L''hélium'], 'fr', true, 'Lors de la respiration, nous inspirons de l''oxygène et expirons du dioxyde de carbone (CO2).'),
('sciences', 1, 'Comment s''appelle le petit de la vache ?', 'Le veau', ARRAY['L''agneau', 'Le poulain', 'Le chevreau'], 'fr', true, 'Le veau est le petit de la vache et du taureau.'),
('sciences', 1, 'Quel est l''organe qui nous permet de voir ?', 'L''œil', ARRAY['L''oreille', 'Le nez', 'La langue'], 'fr', true, 'L''œil capte la lumière et transmet les informations visuelles au cerveau.'),
('sciences', 1, 'De quelle matière sont faites les dents ?', 'D''émail', ARRAY['D''os', 'De cartilage', 'De kératine'], 'fr', true, 'L''émail dentaire est la substance la plus dure du corps humain.'),
('sciences', 1, 'Quel animal pond des œufs et a des plumes ?', 'L''oiseau', ARRAY['Le serpent', 'Le poisson', 'La tortue'], 'fr', true, 'Les oiseaux sont les seuls animaux à posséder des plumes et pondent des œufs.'),
('sciences', 1, 'L''eau bout à quelle température au niveau de la mer ?', '100°C', ARRAY['50°C', '80°C', '120°C'], 'fr', true, 'L''eau pure bout à 100 degrés Celsius à pression atmosphérique normale.'),
('sciences', 1, 'Quel est le plus grand continent ?', 'L''Asie', ARRAY['L''Afrique', 'L''Amérique du Nord', 'L''Europe'], 'fr', true, 'L''Asie est le plus grand continent avec environ 44,6 millions de km².'),
('sciences', 1, 'De quoi est recouverte la majorité de la surface terrestre ?', 'D''eau', ARRAY['De forêts', 'De déserts', 'De montagnes'], 'fr', true, 'Environ 71% de la surface de la Terre est recouverte d''eau.'),
('sciences', 1, 'Quel astre brille la nuit et change de forme au cours du mois ?', 'La Lune', ARRAY['Le Soleil', 'Vénus', 'Mars'], 'fr', true, 'La Lune passe par différentes phases (croissant, quartier, pleine lune) au cours d''un cycle de 29,5 jours.'),
('sciences', 1, 'Quel est le contraire du froid ?', 'Le chaud', ARRAY['Le tiède', 'Le glacé', 'Le frais'], 'fr', true, 'Le chaud et le froid sont deux sensations opposées liées à la température.'),
('sciences', 1, 'Comment s''appelle le phénomène quand il pleut et qu''il y a du soleil en même temps ?', 'Une éclaircie', ARRAY['Un orage', 'Une tempête', 'Une averse'], 'fr', true, 'Ce phénomène peut provoquer l''apparition d''un arc-en-ciel.'),
('sciences', 1, 'Quel animal est le meilleur ami de l''homme ?', 'Le chien', ARRAY['Le chat', 'Le cheval', 'Le lapin'], 'fr', true, 'Le chien a été domestiqué il y a plus de 15 000 ans et est souvent appelé le meilleur ami de l''homme.'),
('sciences', 1, 'Combien de sens possède l''être humain ?', '5', ARRAY['3', '4', '6'], 'fr', true, 'Les cinq sens sont la vue, l''ouïe, l''odorat, le goût et le toucher.'),
('sciences', 1, 'De quelle couleur est le sang dans nos veines ?', 'Rouge', ARRAY['Bleu', 'Violet', 'Vert'], 'fr', true, 'Le sang est toujours rouge, plus foncé quand il est pauvre en oxygène, plus vif quand il en est riche.'),
('sciences', 1, 'Quel phénomène naturel fait tomber de la neige ?', 'Les précipitations', ARRAY['Les éruptions', 'Les marées', 'Les séismes'], 'fr', true, 'La neige se forme quand la vapeur d''eau gèle dans les nuages et tombe sous forme de cristaux.'),
('sciences', 1, 'Quel insecte produit du miel ?', 'L''abeille', ARRAY['La guêpe', 'Le bourdon', 'La mouche'], 'fr', true, 'Les abeilles produisent du miel à partir du nectar des fleurs.'),
('sciences', 1, 'Combien de pattes a un chat ?', '4', ARRAY['2', '6', '8'], 'fr', true, 'Les chats, comme tous les félins, sont des quadrupèdes avec 4 pattes.'),
('sciences', 1, 'Qu''est-ce qui provoque le jour et la nuit ?', 'La rotation de la Terre', ARRAY['La rotation de la Lune', 'Le mouvement du Soleil', 'Les saisons'], 'fr', true, 'La Terre tourne sur elle-même en 24 heures, créant l''alternance jour/nuit.'),
('sciences', 1, 'Quel est l''état de la glace ?', 'Solide', ARRAY['Liquide', 'Gazeux', 'Plasma'], 'fr', true, 'La glace est de l''eau à l''état solide, formée en dessous de 0°C.'),
('sciences', 1, 'Quel est le fleuve le plus long du monde ?', 'Le Nil', ARRAY['L''Amazone', 'Le Mississippi', 'Le Yangtsé'], 'fr', true, 'Le Nil mesure environ 6 650 km, ce qui en fait le fleuve le plus long du monde.'),
('sciences', 1, 'Les dauphins sont-ils des poissons ou des mammifères ?', 'Des mammifères', ARRAY['Des poissons', 'Des reptiles', 'Des amphibiens'], 'fr', true, 'Les dauphins sont des mammifères marins qui respirent de l''air et allaitent leurs petits.'),
('sciences', 1, 'Quel est le plus haut sommet du monde ?', 'L''Everest', ARRAY['Le K2', 'Le Mont Blanc', 'Le Kilimandjaro'], 'fr', true, 'L''Everest culmine à 8 849 mètres dans l''Himalaya.'),
('sciences', 1, 'De quoi a besoin une plante pour pousser ?', 'D''eau, de lumière et de terre', ARRAY['Uniquement d''eau', 'Uniquement de lumière', 'Uniquement de terre'], 'fr', true, 'Les plantes ont besoin d''eau, de lumière, de nutriments du sol et de CO2 pour se développer.'),
('sciences', 1, 'Quel est le plus rapide : la lumière ou le son ?', 'La lumière', ARRAY['Le son', 'Ils vont à la même vitesse', 'Cela dépend du temps'], 'fr', true, 'La lumière voyage à environ 300 000 km/s, tandis que le son ne parcourt que 340 m/s dans l''air.'),
('sciences', 1, 'Combien y a-t-il de saisons dans une année ?', '4', ARRAY['2', '3', '6'], 'fr', true, 'Les quatre saisons sont le printemps, l''été, l''automne et l''hiver.'),
('sciences', 1, 'Quel organe du corps humain est protégé par le crâne ?', 'Le cerveau', ARRAY['Le cœur', 'Les poumons', 'L''estomac'], 'fr', true, 'Le crâne est une boîte osseuse qui protège le cerveau des chocs.'),
('sciences', 1, 'Les grenouilles naissent-elles dans l''eau ou sur terre ?', 'Dans l''eau', ARRAY['Sur terre', 'Dans les arbres', 'Dans le sable'], 'fr', true, 'Les grenouilles pondent leurs œufs dans l''eau, où les têtards se développent avant de devenir adultes.'),
('sciences', 1, 'Qu''est-ce qui fait que les étoiles brillent ?', 'Des réactions nucléaires', ARRAY['De l''électricité', 'Du feu', 'La réflexion du Soleil'], 'fr', true, 'Les étoiles brillent grâce à la fusion nucléaire de l''hydrogène en hélium dans leur cœur.'),
('sciences', 1, 'Quel est l''animal terrestre le plus rapide ?', 'Le guépard', ARRAY['Le lion', 'Le loup', 'Le cheval'], 'fr', true, 'Le guépard peut atteindre 120 km/h sur de courtes distances.'),
('sciences', 1, 'De quel arbre proviennent les glands ?', 'Le chêne', ARRAY['Le sapin', 'Le bouleau', 'L''érable'], 'fr', true, 'Les glands sont les fruits du chêne et servent de nourriture à de nombreux animaux.'),
('sciences', 1, 'Quel est l''aliment principal des pandas ?', 'Le bambou', ARRAY['Les insectes', 'Le poisson', 'Les fruits'], 'fr', true, 'Le panda géant se nourrit presque exclusivement de bambou, jusqu''à 38 kg par jour.'),
('sciences', 1, 'Quel phénomène météo est accompagné d''éclairs et de tonnerre ?', 'L''orage', ARRAY['La tempête de neige', 'Le brouillard', 'La canicule'], 'fr', true, 'L''orage est un phénomène météorologique avec des décharges électriques (éclairs) et des ondes sonores (tonnerre).'),
('sciences', 1, 'L''ours polaire vit dans quel type d''environnement ?', 'L''Arctique', ARRAY['La jungle', 'Le désert', 'La montagne'], 'fr', true, 'L''ours polaire vit dans la région arctique et est parfaitement adapté au froid extrême.'),
('sciences', 1, 'Comment s''appelle le bébé du chat ?', 'Le chaton', ARRAY['Le chiot', 'Le poussin', 'Le faon'], 'fr', true, 'Le chaton est le petit du chat, il naît aveugle et sourd.'),
('sciences', 1, 'Quelle est la couleur du soleil vue depuis l''espace ?', 'Blanc', ARRAY['Jaune', 'Orange', 'Rouge'], 'fr', true, 'Le Soleil émet une lumière blanche ; c''est l''atmosphère terrestre qui lui donne une teinte jaune.'),
('sciences', 1, 'Quel est le plus petit os du corps humain ?', 'L''étrier', ARRAY['Le marteau', 'L''enclume', 'La rotule'], 'fr', true, 'L''étrier, situé dans l''oreille moyenne, mesure environ 3 mm.'),
('sciences', 1, 'Quelle matière recouvre le corps des poissons ?', 'Des écailles', ARRAY['De la fourrure', 'Des plumes', 'De la peau lisse'], 'fr', true, 'La plupart des poissons sont recouverts d''écailles qui les protègent.'),
('sciences', 1, 'Quel fruit est connu pour être riche en vitamine C ?', 'L''orange', ARRAY['La banane', 'La pomme', 'La poire'], 'fr', true, 'Les agrumes comme l''orange sont riches en vitamine C, essentielle au système immunitaire.'),
('sciences', 1, 'Les serpents sont-ils des reptiles ou des amphibiens ?', 'Des reptiles', ARRAY['Des amphibiens', 'Des mammifères', 'Des poissons'], 'fr', true, 'Les serpents sont des reptiles à sang froid, dépourvus de pattes.'),
('sciences', 1, 'Quelle partie de la plante absorbe l''eau dans le sol ?', 'Les racines', ARRAY['Les feuilles', 'La tige', 'Les fleurs'], 'fr', true, 'Les racines absorbent l''eau et les minéraux du sol pour nourrir la plante.'),
('sciences', 1, 'Quel est l''animal qui porte sa maison sur son dos ?', 'L''escargot', ARRAY['Le hérisson', 'Le crabe', 'La souris'], 'fr', true, 'L''escargot porte une coquille sur son dos dans laquelle il peut se rétracter pour se protéger.'),
('sciences', 1, 'Combien de doigts a une main humaine ?', '5', ARRAY['4', '6', '3'], 'fr', true, 'Chaque main humaine possède 5 doigts : pouce, index, majeur, annulaire et auriculaire.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('sciences', 2, 'Quel est le gaz le plus abondant dans l''atmosphère ?', 'L''azote', ARRAY['L''oxygène', 'Le CO2', 'L''argon'], 'fr', true, 'L''azote représente environ 78% de l''atmosphère terrestre.'),
('sciences', 2, 'Quelle est l''unité de mesure de la température dans le système international ?', 'Le Kelvin', ARRAY['Le Celsius', 'Le Fahrenheit', 'Le Rankine'], 'fr', true, 'Le Kelvin est l''unité SI de température, avec 0 K correspondant au zéro absolu.'),
('sciences', 2, 'Quel savant français a inventé la pasteurisation ?', 'Louis Pasteur', ARRAY['Marie Curie', 'Antoine Lavoisier', 'Claude Bernard'], 'fr', true, 'Louis Pasteur a mis au point la pasteurisation pour éliminer les micro-organismes dans les aliments.'),
('sciences', 2, 'Comment appelle-t-on un animal qui mange uniquement des plantes ?', 'Un herbivore', ARRAY['Un carnivore', 'Un omnivore', 'Un insectivore'], 'fr', true, 'Les herbivores se nourrissent exclusivement de végétaux, comme les vaches ou les lapins.'),
('sciences', 2, 'Quelle planète est surnommée l''étoile du Berger ?', 'Vénus', ARRAY['Mars', 'Jupiter', 'Mercure'], 'fr', true, 'Vénus est très lumineuse et visible à l''aube ou au crépuscule, d''où son surnom d''étoile du Berger.'),
('sciences', 2, 'Quel est le principal composant du soleil ?', 'L''hydrogène', ARRAY['L''hélium', 'Le carbone', 'Le fer'], 'fr', true, 'Le Soleil est composé d''environ 73% d''hydrogène et 25% d''hélium.'),
('sciences', 2, 'Quel os protège le cœur et les poumons ?', 'Les côtes', ARRAY['Le sternum', 'La clavicule', 'L''omoplate'], 'fr', true, 'La cage thoracique formée par les côtes protège les organes vitaux comme le cœur et les poumons.'),
('sciences', 2, 'Comment appelle-t-on la science qui étudie les tremblements de terre ?', 'La sismologie', ARRAY['La volcanologie', 'La géologie', 'La météorologie'], 'fr', true, 'La sismologie est la branche de la géophysique qui étudie les séismes.'),
('sciences', 2, 'Quel est le plus grand désert du monde ?', 'Le Sahara', ARRAY['Le Gobi', 'L''Antarctique', 'L''Atacama'], 'fr', true, 'Le Sahara couvre environ 9 millions de km² en Afrique du Nord. Note : l''Antarctique est le plus grand désert froid.'),
('sciences', 2, 'Quel type de roche se forme à partir de lave refroidie ?', 'La roche volcanique (ignée)', ARRAY['La roche sédimentaire', 'La roche métamorphique', 'La roche calcaire'], 'fr', true, 'Les roches ignées se forment quand le magma ou la lave se refroidit et se solidifie.'),
('sciences', 2, 'Quel élément chimique a pour symbole O ?', 'L''oxygène', ARRAY['L''or', 'L''osmium', 'L''oganesson'], 'fr', true, 'L''oxygène a pour symbole O et pour numéro atomique 8.'),
('sciences', 2, 'Combien de litres de sang contient environ le corps humain adulte ?', '5 litres', ARRAY['3 litres', '8 litres', '10 litres'], 'fr', true, 'Un adulte moyen possède environ 5 litres de sang en circulation.'),
('sciences', 2, 'Quel scientifique italien est connu pour avoir amélioré le télescope ?', 'Galilée', ARRAY['Léonard de Vinci', 'Alessandro Volta', 'Enrico Fermi'], 'fr', true, 'Galilée a amélioré le télescope et découvert les lunes de Jupiter en 1610.'),
('sciences', 2, 'Qu''est-ce que le magma ?', 'De la roche en fusion sous la surface terrestre', ARRAY['De l''eau chaude souterraine', 'Un gaz volcanique', 'Un type de minéral'], 'fr', true, 'Le magma est de la roche fondue située sous la croûte terrestre ; il devient lave en surface.'),
('sciences', 2, 'Quelle est la formule chimique du sel de table ?', 'NaCl', ARRAY['KCl', 'CaCl2', 'NaOH'], 'fr', true, 'Le sel de table est du chlorure de sodium, composé d''un atome de sodium et d''un atome de chlore.'),
('sciences', 2, 'Quelle partie du corps humain contient le plus d''eau ?', 'Le cerveau', ARRAY['Les os', 'Les muscles', 'La peau'], 'fr', true, 'Le cerveau est composé d''environ 75% d''eau.'),
('sciences', 2, 'Comment s''appelle l''étude des étoiles et de l''univers ?', 'L''astronomie', ARRAY['L''astrologie', 'La cosmétique', 'L''astrophysique'], 'fr', true, 'L''astronomie est la science qui étudie les astres, les planètes et l''univers.'),
('sciences', 2, 'Quel phénomène explique que les objets tombent vers le sol ?', 'La gravitation', ARRAY['Le magnétisme', 'L''électricité statique', 'La pression atmosphérique'], 'fr', true, 'La gravitation est la force d''attraction entre deux masses, décrite par Newton puis Einstein.'),
('sciences', 2, 'Quel virus a causé la pandémie mondiale en 2020 ?', 'Le SARS-CoV-2', ARRAY['Le virus Ebola', 'Le virus H1N1', 'Le virus Zika'], 'fr', true, 'Le SARS-CoV-2 est le coronavirus responsable de la maladie COVID-19.'),
('sciences', 2, 'Comment s''appelle la couche d''ozone et où se situe-t-elle ?', 'Dans la stratosphère', ARRAY['Dans la troposphère', 'Dans la mésosphère', 'Dans la thermosphère'], 'fr', true, 'La couche d''ozone se situe dans la stratosphère, entre 15 et 35 km d''altitude.'),
('sciences', 2, 'Quel est le symbole chimique de l''argent ?', 'Ag', ARRAY['Ar', 'Au', 'Al'], 'fr', true, 'Ag vient du latin Argentum. L''argent a le numéro atomique 47.'),
('sciences', 2, 'Quel est le rôle principal des globules blancs ?', 'Défendre le corps contre les infections', ARRAY['Transporter l''oxygène', 'Coaguler le sang', 'Digérer les aliments'], 'fr', true, 'Les globules blancs (leucocytes) font partie du système immunitaire et combattent les infections.'),
('sciences', 2, 'Quel est le point d''ébullition de l''eau en Fahrenheit ?', '212°F', ARRAY['100°F', '180°F', '250°F'], 'fr', true, 'L''eau bout à 100°C, ce qui correspond à 212°F.'),
('sciences', 2, 'Quelle est la différence entre un atome et une molécule ?', 'Une molécule est formée de plusieurs atomes liés', ARRAY['Un atome est plus grand qu''une molécule', 'Ce sont la même chose', 'Une molécule est une particule subatomique'], 'fr', true, 'Un atome est la plus petite unité d''un élément ; une molécule résulte de la combinaison d''atomes.'),
('sciences', 2, 'Quel est le nom du phénomène de montée et descente des eaux de mer ?', 'Les marées', ARRAY['Les courants', 'Les vagues', 'Les tsunamis'], 'fr', true, 'Les marées sont causées par l''attraction gravitationnelle de la Lune et du Soleil sur les océans.'),
('sciences', 2, 'Combien de paires de chromosomes possède un être humain ?', '23 paires', ARRAY['22 paires', '24 paires', '46 paires'], 'fr', true, 'L''humain possède 23 paires de chromosomes, soit 46 au total.'),
('sciences', 2, 'Quel est le métal le plus conducteur d''électricité ?', 'L''argent', ARRAY['Le cuivre', 'L''or', 'L''aluminium'], 'fr', true, 'L''argent est le meilleur conducteur électrique, suivi du cuivre.'),
('sciences', 2, 'Comment appelle-t-on un volcan qui n''est plus en activité ?', 'Un volcan éteint', ARRAY['Un volcan dormant', 'Un volcan actif', 'Un volcan sous-marin'], 'fr', true, 'Un volcan éteint n''a plus aucune chance d''entrer en éruption, contrairement au volcan dormant.'),
('sciences', 2, 'Quelle est la planète la plus chaude du système solaire ?', 'Vénus', ARRAY['Mercure', 'Mars', 'Jupiter'], 'fr', true, 'Malgré sa distance au Soleil, Vénus est la plus chaude grâce à son effet de serre intense (465°C).'),
('sciences', 2, 'Quel est le principal organe de la respiration ?', 'Les poumons', ARRAY['Le cœur', 'Le diaphragme', 'La trachée'], 'fr', true, 'Les poumons permettent les échanges gazeux entre l''air et le sang.'),
('sciences', 2, 'Quel gaz est utilisé dans les ballons qui flottent ?', 'L''hélium', ARRAY['L''hydrogène', 'L''azote', 'L''oxygène'], 'fr', true, 'L''hélium est un gaz plus léger que l''air et non inflammable, idéal pour les ballons.'),
('sciences', 2, 'Comment s''appelle la science qui étudie les insectes ?', 'L''entomologie', ARRAY['La zoologie', 'La botanique', 'L''ornithologie'], 'fr', true, 'L''entomologie est la branche de la zoologie consacrée à l''étude des insectes.'),
('sciences', 2, 'Quel est le symbole chimique du cuivre ?', 'Cu', ARRAY['Co', 'Cr', 'Ca'], 'fr', true, 'Cu vient du latin Cuprum. Le cuivre est un excellent conducteur utilisé dans les fils électriques.'),
('sciences', 2, 'Qu''est-ce qu''un fossile ?', 'Les restes ou traces d''un organisme ancien conservés dans la roche', ARRAY['Un type de minéral', 'Une roche volcanique', 'Un cristal naturel'], 'fr', true, 'Les fossiles sont des traces d''êtres vivants préservées dans les roches sédimentaires sur des millions d''années.'),
('sciences', 2, 'Quel est le plus long fleuve de France ?', 'La Loire', ARRAY['La Seine', 'Le Rhône', 'La Garonne'], 'fr', true, 'La Loire mesure environ 1 012 km, ce qui en fait le plus long fleuve de France.'),
('sciences', 2, 'Quel organe produit la bile ?', 'Le foie', ARRAY['L''estomac', 'Le pancréas', 'La vésicule biliaire'], 'fr', true, 'Le foie produit la bile, qui est ensuite stockée dans la vésicule biliaire et aide à digérer les graisses.'),
('sciences', 2, 'Quel est le nombre de protons dans un atome d''hydrogène ?', '1', ARRAY['2', '0', '3'], 'fr', true, 'L''hydrogène est l''élément le plus simple avec un seul proton et un seul électron.'),
('sciences', 2, 'Comment appelle-t-on les animaux qui vivent la nuit ?', 'Nocturnes', ARRAY['Diurnes', 'Crépusculaires', 'Migrateurs'], 'fr', true, 'Les animaux nocturnes, comme la chouette ou le hérisson, sont actifs principalement la nuit.'),
('sciences', 2, 'Quelle est la température du corps humain en bonne santé ?', '37°C', ARRAY['36°C', '38°C', '39°C'], 'fr', true, 'La température normale du corps humain est d''environ 37°C (98.6°F).'),
('sciences', 2, 'Quel est le plus petit continent ?', 'L''Océanie', ARRAY['L''Europe', 'L''Antarctique', 'L''Amérique du Sud'], 'fr', true, 'L''Océanie (ou continent australien) est le plus petit continent avec environ 8,5 millions de km².'),
('sciences', 2, 'Qui a inventé le vaccin contre la rage ?', 'Louis Pasteur', ARRAY['Edward Jenner', 'Robert Koch', 'Alexander Fleming'], 'fr', true, 'Louis Pasteur a mis au point le vaccin contre la rage en 1885.'),
('sciences', 2, 'Quel est le processus par lequel les plantes fabriquent leur nourriture ?', 'La photosynthèse', ARRAY['La respiration', 'La fermentation', 'La digestion'], 'fr', true, 'La photosynthèse utilise la lumière, le CO2 et l''eau pour produire du glucose et de l''oxygène.'),
('sciences', 2, 'De quoi est composé un diamant ?', 'De carbone pur', ARRAY['De silice', 'De quartz', 'De calcium'], 'fr', true, 'Le diamant est constitué d''atomes de carbone arrangés en structure cristalline très dense.'),
('sciences', 2, 'Combien de temps la Terre met-elle pour faire le tour du Soleil ?', '365 jours (1 an)', ARRAY['30 jours', '180 jours', '500 jours'], 'fr', true, 'La Terre effectue une révolution complète autour du Soleil en environ 365,25 jours.'),
('sciences', 2, 'Quel est le rôle principal du squelette ?', 'Soutenir le corps et protéger les organes', ARRAY['Produire de l''énergie', 'Digérer les aliments', 'Réguler la température'], 'fr', true, 'Le squelette fournit la structure du corps, protège les organes vitaux et permet le mouvement.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('sciences', 3, 'Quelle est l''unité de mesure de la résistance électrique ?', 'L''Ohm', ARRAY['Le Volt', 'L''Ampère', 'Le Watt'], 'fr', true, 'L''Ohm (Ω) mesure la résistance électrique, nommé d''après le physicien Georg Ohm.'),
('sciences', 3, 'Quel scientifique français a découvert le radium avec son mari Pierre ?', 'Marie Curie', ARRAY['Irène Joliot-Curie', 'Émilie du Châtelet', 'Sophie Germain'], 'fr', true, 'Marie Curie a découvert le radium et le polonium, et a reçu deux prix Nobel.'),
('sciences', 3, 'Quel est le nom de la plus grande structure vivante sur Terre ?', 'La Grande Barrière de corail', ARRAY['La forêt amazonienne', 'Le réseau fongique souterrain', 'Les prairies africaines'], 'fr', true, 'La Grande Barrière de corail en Australie s''étend sur plus de 2 300 km.'),
('sciences', 3, 'Combien de temps met la lumière pour aller du Soleil à la Terre ?', 'Environ 8 minutes', ARRAY['Environ 1 seconde', 'Environ 1 heure', 'Environ 30 minutes'], 'fr', true, 'La lumière parcourt les 150 millions de km entre le Soleil et la Terre en environ 8 min 20 s.'),
('sciences', 3, 'Quelle est la loi fondamentale de la thermodynamique qui stipule que l''énergie se conserve ?', 'Le premier principe', ARRAY['Le deuxième principe', 'Le troisième principe', 'Le principe zéro'], 'fr', true, 'Le premier principe de la thermodynamique affirme que l''énergie totale d''un système isolé est constante.'),
('sciences', 3, 'Quel chimiste français est considéré comme le père de la chimie moderne ?', 'Antoine Lavoisier', ARRAY['Louis Pasteur', 'Joseph Gay-Lussac', 'Henri Moissan'], 'fr', true, 'Lavoisier a identifié l''oxygène et l''hydrogène et a réformé la nomenclature chimique.'),
('sciences', 3, 'Quel phénomène optique décompose la lumière blanche en un spectre de couleurs ?', 'La dispersion', ARRAY['La réfraction', 'La diffraction', 'La réflexion'], 'fr', true, 'La dispersion sépare les différentes longueurs d''onde de la lumière blanche, comme dans un prisme.'),
('sciences', 3, 'Quel est le nombre d''Avogadro ?', '6,022 × 10²³', ARRAY['3,14 × 10⁸', '1,602 × 10⁻¹⁹', '9,81 × 10¹'], 'fr', true, 'Le nombre d''Avogadro correspond au nombre d''entités dans une mole de matière.'),
('sciences', 3, 'Comment s''appelle le processus de transformation d''un solide directement en gaz ?', 'La sublimation', ARRAY['L''évaporation', 'La fusion', 'La condensation'], 'fr', true, 'La sublimation est le passage direct de l''état solide à l''état gazeux, comme la neige carbonique.'),
('sciences', 3, 'Quel est le rôle de l''ADN dans les cellules ?', 'Stocker l''information génétique', ARRAY['Produire de l''énergie', 'Transporter l''oxygène', 'Digérer les nutriments'], 'fr', true, 'L''ADN contient les instructions génétiques nécessaires au développement et au fonctionnement des organismes.'),
('sciences', 3, 'Quelle est la particule élémentaire porteuse de la force électromagnétique ?', 'Le photon', ARRAY['L''électron', 'Le gluon', 'Le graviton'], 'fr', true, 'Le photon est la particule médiatrice de l''interaction électromagnétique, y compris la lumière.'),
('sciences', 3, 'Quel est l''élément chimique le plus abondant dans l''univers ?', 'L''hydrogène', ARRAY['L''hélium', 'L''oxygène', 'Le carbone'], 'fr', true, 'L''hydrogène représente environ 75% de la masse visible de l''univers.'),
('sciences', 3, 'Qui a formulé les lois de l''hérédité ?', 'Gregor Mendel', ARRAY['Charles Darwin', 'Louis Pasteur', 'James Watson'], 'fr', true, 'Gregor Mendel, moine et botaniste, a découvert les lois de l''hérédité grâce à ses expériences sur les pois.'),
('sciences', 3, 'Quelle est la différence entre la mitose et la méiose ?', 'La méiose produit des cellules avec la moitié des chromosomes', ARRAY['La mitose est plus rapide', 'La méiose ne concerne que les plantes', 'Ce sont des synonymes'], 'fr', true, 'La mitose produit 2 cellules identiques, la méiose produit 4 cellules avec la moitié des chromosomes pour la reproduction.'),
('sciences', 3, 'Quel est le nom du plus grand os du corps humain ?', 'Le fémur', ARRAY['Le tibia', 'L''humérus', 'Le péroné'], 'fr', true, 'Le fémur, l''os de la cuisse, est le plus long et le plus solide du corps humain.'),
('sciences', 3, 'Quel phénomène cause les aurores boréales ?', 'L''interaction des particules solaires avec la magnétosphère', ARRAY['La réflexion de la lumière sur la glace', 'Les éruptions volcaniques', 'La pollution lumineuse'], 'fr', true, 'Les aurores boréales se produisent quand les particules chargées du vent solaire excitent les molécules atmosphériques.'),
('sciences', 3, 'Quel est le numéro atomique du carbone ?', '6', ARRAY['8', '12', '14'], 'fr', true, 'Le carbone a 6 protons dans son noyau, d''où son numéro atomique 6.'),
('sciences', 3, 'Comment appelle-t-on les organismes microscopiques unicellulaires sans noyau ?', 'Les procaryotes', ARRAY['Les eucaryotes', 'Les virus', 'Les protistes'], 'fr', true, 'Les procaryotes (bactéries et archées) sont des organismes unicellulaires sans noyau délimité.'),
('sciences', 3, 'Quelle est la troisième loi de Newton ?', 'À toute action correspond une réaction égale et opposée', ARRAY['F = ma', 'Un objet au repos reste au repos', 'L''énergie se conserve'], 'fr', true, 'La troisième loi de Newton (principe d''action-réaction) stipule que les forces vont toujours par paires opposées.'),
('sciences', 3, 'Quel physicien français a donné son nom à l''unité de pression ?', 'Blaise Pascal', ARRAY['André-Marie Ampère', 'Charles Coulomb', 'Joseph Fourier'], 'fr', true, 'Le pascal (Pa) est l''unité de pression du système international, nommée en l''honneur de Blaise Pascal.'),
('sciences', 3, 'Qu''est-ce qu''un isotope ?', 'Un atome avec le même nombre de protons mais un nombre différent de neutrons', ARRAY['Un atome sans électrons', 'Un atome chargé électriquement', 'Un type de molécule'], 'fr', true, 'Les isotopes d''un même élément ont le même numéro atomique mais des masses atomiques différentes.'),
('sciences', 3, 'Quel est le nom de la couche interne de la Terre ?', 'Le noyau', ARRAY['Le manteau', 'La croûte', 'L''asthénosphère'], 'fr', true, 'Le noyau terrestre se divise en noyau externe liquide et noyau interne solide, principalement en fer et nickel.'),
('sciences', 3, 'Quelle théorie explique la dérive des continents ?', 'La tectonique des plaques', ARRAY['La théorie de la relativité', 'La théorie du Big Bang', 'La théorie de l''évolution'], 'fr', true, 'La tectonique des plaques explique le mouvement des continents sur les plaques lithosphériques.'),
('sciences', 3, 'Combien d''éléments chimiques le tableau périodique contient-il actuellement ?', '118', ARRAY['92', '108', '126'], 'fr', true, 'Le tableau périodique contient 118 éléments chimiques, du numéro 1 (hydrogène) au 118 (oganesson).'),
('sciences', 3, 'Comment s''appelle l''hormone du stress ?', 'Le cortisol', ARRAY['L''adrénaline', 'L''insuline', 'La mélatonine'], 'fr', true, 'Le cortisol, sécrété par les glandes surrénales, est souvent appelé l''hormone du stress.'),
('sciences', 3, 'Quel est le nom du processus par lequel les bactéries se reproduisent ?', 'La fission binaire', ARRAY['La mitose', 'La méiose', 'La conjugaison'], 'fr', true, 'La fission binaire est le mode de reproduction asexuée des bactéries, qui se divisent en deux cellules identiques.'),
('sciences', 3, 'Quel est l''effet Doppler ?', 'Le changement de fréquence d''une onde quand la source se déplace', ARRAY['La courbure de la lumière par la gravité', 'L''absorption de la lumière par un gaz', 'La diffusion de la lumière dans l''atmosphère'], 'fr', true, 'L''effet Doppler explique pourquoi le son d''une ambulance change de tonalité en passant.'),
('sciences', 3, 'Quelle est la formule chimique du glucose ?', 'C₆H₁₂O₆', ARRAY['C₂H₅OH', 'CH₄', 'C₁₂H₂₂O₁₁'], 'fr', true, 'Le glucose (C₆H₁₂O₆) est un sucre simple, principale source d''énergie des cellules.'),
('sciences', 3, 'Quel est le rôle de l''hémoglobine ?', 'Transporter l''oxygène dans le sang', ARRAY['Coaguler le sang', 'Combattre les infections', 'Réguler la glycémie'], 'fr', true, 'L''hémoglobine est une protéine des globules rouges qui lie l''oxygène pour le transporter dans le corps.'),
('sciences', 3, 'Quel physicien a découvert l''électromagnétisme ?', 'Michael Faraday', ARRAY['James Maxwell', 'André-Marie Ampère', 'Nikola Tesla'], 'fr', true, 'Michael Faraday a découvert l''induction électromagnétique et posé les bases de l''électromagnétisme.'),
('sciences', 3, 'Que mesure l''échelle de Mohs ?', 'La dureté des minéraux', ARRAY['L''acidité d''une solution', 'La force d''un séisme', 'La luminosité d''une étoile'], 'fr', true, 'L''échelle de Mohs classe les minéraux de 1 (talc, très tendre) à 10 (diamant, très dur).'),
('sciences', 3, 'Quel est le plus grand organe interne du corps humain ?', 'Le foie', ARRAY['Les poumons', 'L''estomac', 'Le cerveau'], 'fr', true, 'Le foie pèse environ 1,5 kg et remplit plus de 500 fonctions métaboliques.'),
('sciences', 3, 'Qu''est-ce qu''une année-lumière ?', 'La distance parcourue par la lumière en un an', ARRAY['Le temps que met la lumière pour atteindre la Terre', 'Une unité de temps', 'La durée d''une orbite terrestre'], 'fr', true, 'Une année-lumière vaut environ 9 461 milliards de km.'),
('sciences', 3, 'Quel est le rôle du diaphragme dans la respiration ?', 'Il se contracte pour permettre l''inspiration', ARRAY['Il filtre l''air', 'Il produit du mucus', 'Il réchauffe l''air'], 'fr', true, 'Le diaphragme est un muscle qui, en se contractant, augmente le volume pulmonaire et permet l''entrée d''air.'),
('sciences', 3, 'Qu''est-ce que l''effet de serre ?', 'Le piégeage de la chaleur dans l''atmosphère par certains gaz', ARRAY['La destruction de la couche d''ozone', 'Le réchauffement du sol par le soleil', 'La réflexion de la lumière par les glaciers'], 'fr', true, 'L''effet de serre est un phénomène naturel amplifié par les gaz comme le CO2 et le méthane.'),
('sciences', 3, 'Qui a découvert la structure en double hélice de l''ADN ?', 'Watson et Crick', ARRAY['Mendel et Darwin', 'Pasteur et Koch', 'Curie et Rutherford'], 'fr', true, 'James Watson et Francis Crick ont décrit la structure de l''ADN en 1953, avec les travaux de Rosalind Franklin.'),
('sciences', 3, 'Quel est l''organite cellulaire responsable de la synthèse des protéines ?', 'Le ribosome', ARRAY['La mitochondrie', 'Le lysosome', 'L''appareil de Golgi'], 'fr', true, 'Les ribosomes traduisent l''ARN messager en protéines.'),
('sciences', 3, 'Quel physicien français a donné son nom à l''unité de charge électrique ?', 'Charles Coulomb', ARRAY['André-Marie Ampère', 'Blaise Pascal', 'Joseph Fourier'], 'fr', true, 'Le coulomb (C) est l''unité de charge électrique, nommée d''après Charles-Augustin de Coulomb.'),
('sciences', 3, 'Qu''est-ce que la biosphère ?', 'L''ensemble des écosystèmes de la Terre où la vie existe', ARRAY['L''atmosphère terrestre', 'Le noyau de la Terre', 'La couche d''ozone'], 'fr', true, 'La biosphère englobe tous les milieux où se trouvent des êtres vivants, de la profondeur des océans aux montagnes.'),
('sciences', 3, 'Quelle est la principale cause de l''extinction des dinosaures ?', 'L''impact d''un astéroïde il y a 66 millions d''années', ARRAY['Une éruption volcanique', 'Un changement climatique lent', 'Une épidémie'], 'fr', true, 'Un astéroïde d''environ 10 km a frappé le Yucatán, provoquant une extinction massive il y a 66 millions d''années.'),
('sciences', 3, 'Quel est le type de liaison dans une molécule d''eau (H₂O) ?', 'Liaison covalente polaire', ARRAY['Liaison ionique', 'Liaison métallique', 'Liaison covalente non polaire'], 'fr', true, 'Les atomes d''hydrogène et d''oxygène partagent des électrons de manière inégale, créant une liaison covalente polaire.'),
('sciences', 3, 'Comment s''appelle le phénomène de résistance des bactéries aux antibiotiques ?', 'L''antibiorésistance', ARRAY['La mutation virale', 'L''immunodéficience', 'La biorésistance'], 'fr', true, 'L''antibiorésistance survient quand les bactéries évoluent pour survivre aux antibiotiques, un enjeu majeur de santé publique.'),
('sciences', 3, 'Quel type de rayonnement ultraviolet est le plus dangereux ?', 'Les UV-C', ARRAY['Les UV-A', 'Les UV-B', 'Les infrarouges'], 'fr', true, 'Les UV-C sont les plus énergétiques et dangereux, mais sont heureusement filtrés par la couche d''ozone.'),
('sciences', 3, 'Quelle planète possède le plus grand nombre de lunes connues ?', 'Saturne', ARRAY['Jupiter', 'Uranus', 'Neptune'], 'fr', true, 'Saturne détient le record avec plus de 140 lunes connues.'),
('sciences', 3, 'Qu''est-ce qu''un écosystème ?', 'Un ensemble d''êtres vivants et leur environnement physique en interaction', ARRAY['Un type de forêt tropicale', 'Une chaîne alimentaire', 'Un habitat animal'], 'fr', true, 'Un écosystème comprend les organismes vivants (biotiques) et leur milieu physique (abiotiques) en interaction.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('sciences', 4, 'Quel est le principe d''incertitude de Heisenberg ?', 'On ne peut pas connaître simultanément la position et la vitesse exactes d''une particule', ARRAY['L''énergie ne peut pas être créée ni détruite', 'La lumière est à la fois onde et particule', 'Toute mesure perturbe le système mesuré'], 'fr', true, 'Le principe d''Heisenberg stipule qu''il existe une limite fondamentale à la précision simultanée de la position et de la quantité de mouvement.'),
('sciences', 4, 'Qu''est-ce que la constante de Planck ?', 'La constante reliant l''énergie d''un photon à sa fréquence', ARRAY['La vitesse de la lumière dans le vide', 'La charge d''un électron', 'La masse d''un proton'], 'fr', true, 'La constante de Planck (h ≈ 6,626 × 10⁻³⁴ J·s) est fondamentale en mécanique quantique.'),
('sciences', 4, 'Quel est le nom de la particule élémentaire responsable de la masse ?', 'Le boson de Higgs', ARRAY['Le graviton', 'Le photon', 'Le gluon'], 'fr', true, 'Le boson de Higgs, découvert au CERN en 2012, confère la masse aux particules via le champ de Higgs.'),
('sciences', 4, 'Qu''est-ce que l''entropie en thermodynamique ?', 'Une mesure du désordre d''un système', ARRAY['Une mesure de la température', 'La quantité d''énergie libre', 'La pression interne d''un gaz'], 'fr', true, 'L''entropie mesure le désordre : le deuxième principe de la thermodynamique stipule qu''elle tend à augmenter.'),
('sciences', 4, 'Qu''est-ce que la matière noire ?', 'Une matière hypothétique invisible qui n''émet pas de lumière', ARRAY['De la matière très dense au centre des trous noirs', 'Des particules de poussière interstellaire', 'De l''antimatière'], 'fr', true, 'La matière noire représenterait environ 27% de l''univers mais n''interagit pas avec la lumière.'),
('sciences', 4, 'Quel physicien français a formulé les lois de l''électrodynamique ?', 'André-Marie Ampère', ARRAY['Charles Coulomb', 'Pierre-Simon Laplace', 'Joseph Fourier'], 'fr', true, 'Ampère a fondé l''électrodynamique et formulé la loi reliant courant électrique et champ magnétique.'),
('sciences', 4, 'Qu''est-ce que la résonance magnétique nucléaire (RMN) ?', 'Une technique exploitant les propriétés magnétiques des noyaux atomiques', ARRAY['Une réaction nucléaire contrôlée', 'Un type de radioactivité', 'Une méthode de fusion atomique'], 'fr', true, 'La RMN est utilisée en médecine (IRM) pour créer des images détaillées des organes internes.'),
('sciences', 4, 'Qu''est-ce que la dualité onde-particule ?', 'Le fait que la lumière et la matière présentent à la fois des propriétés d''onde et de particule', ARRAY['Le fait que les ondes sont composées de particules', 'La transformation d''une onde en particule', 'L''annihilation onde-particule'], 'fr', true, 'Louis de Broglie a montré que toute particule possède une longueur d''onde associée.'),
('sciences', 4, 'Qu''est-ce que le CRISPR-Cas9 ?', 'Un outil d''édition génétique', ARRAY['Un type de microscope', 'Un vaccin à ARN messager', 'Un algorithme de séquençage ADN'], 'fr', true, 'CRISPR-Cas9 permet de couper et modifier l''ADN avec précision, révolutionnant la biologie moléculaire.'),
('sciences', 4, 'Quelle est la limite de Roche ?', 'La distance minimale à laquelle un satellite peut orbiter sans être détruit par les forces de marée', ARRAY['La masse maximale d''une étoile à neutrons', 'Le rayon d''un trou noir', 'La distance Terre-Lune minimale'], 'fr', true, 'En deçà de la limite de Roche, les forces de marée d''un corps céleste désintègrent un satellite.'),
('sciences', 4, 'Qu''est-ce que l''intrication quantique ?', 'Un phénomène où deux particules restent corrélées quelle que soit la distance', ARRAY['La fusion de deux atomes', 'L''attraction entre électrons', 'Un type de liaison chimique'], 'fr', true, 'L''intrication quantique, qualifiée d''action fantôme à distance par Einstein, a été confirmée expérimentalement.'),
('sciences', 4, 'Quel est le rôle de l''enzyme télomérase ?', 'Allonger les télomères pour protéger l''ADN lors de la division cellulaire', ARRAY['Couper l''ADN endommagé', 'Transcrire l''ARN en protéine', 'Répliquer les virus'], 'fr', true, 'La télomérase est liée au vieillissement cellulaire et au cancer.'),
('sciences', 4, 'Qu''est-ce que la supraconductivité ?', 'La disparition totale de la résistance électrique à très basse température', ARRAY['La conductivité thermique maximale', 'Un type de semi-conducteur', 'La conductivité dans le vide'], 'fr', true, 'Les supraconducteurs n''ont aucune résistance électrique en dessous d''une température critique.'),
('sciences', 4, 'Quel est le mécanisme de la bioluminescence ?', 'Une réaction chimique produisant de la lumière dans les organismes vivants', ARRAY['La réflexion de la lumière par des écailles', 'L''absorption et la réémission de photons', 'La phosphorescence naturelle'], 'fr', true, 'La bioluminescence implique souvent la luciférine et la luciférase, comme chez les lucioles et certains poissons des abysses.'),
('sciences', 4, 'Qu''est-ce que l''effet photoélectrique ?', 'L''émission d''électrons par un matériau exposé à la lumière', ARRAY['La production de lumière par un courant électrique', 'La conversion de chaleur en électricité', 'La fluorescence des matériaux'], 'fr', true, 'Einstein a reçu le Nobel en 1921 pour son explication de l''effet photoélectrique, prouvant la nature corpusculaire de la lumière.'),
('sciences', 4, 'Qu''est-ce que la catalyse enzymatique ?', 'L''accélération d''une réaction chimique par une enzyme sans être consommée', ARRAY['La production d''enzymes par les cellules', 'La dégradation des protéines', 'La synthèse de l''ADN'], 'fr', true, 'Les enzymes peuvent accélérer les réactions chimiques d''un facteur de 10⁶ à 10¹².'),
('sciences', 4, 'Quelle est la théorie de la relativité restreinte en une phrase ?', 'Les lois de la physique sont les mêmes pour tous les observateurs en mouvement rectiligne uniforme', ARRAY['L''espace et le temps sont absolus', 'La gravité courbe l''espace-temps', 'La masse est convertible en énergie uniquement'], 'fr', true, 'La relativité restreinte d''Einstein (1905) unifie espace et temps et établit E=mc².'),
('sciences', 4, 'Qu''est-ce qu''un quasar ?', 'Un noyau galactique extrêmement lumineux alimenté par un trou noir supermassif', ARRAY['Une étoile à neutrons en rotation', 'Un type de supernova', 'Un amas de galaxies'], 'fr', true, 'Les quasars sont les objets les plus lumineux de l''univers, visibles à des milliards d''années-lumière.'),
('sciences', 4, 'Qu''est-ce que l''apoptose ?', 'La mort cellulaire programmée', ARRAY['La division cellulaire accélérée', 'La fusion de deux cellules', 'La mutation génétique spontanée'], 'fr', true, 'L''apoptose est un processus essentiel au développement et à l''élimination des cellules endommagées.'),
('sciences', 4, 'Quel est le principe de la spectroscopie ?', 'Analyser la lumière émise ou absorbée par la matière pour déterminer sa composition', ARRAY['Mesurer la vitesse de la lumière', 'Observer les étoiles avec un télescope', 'Calculer les distances astronomiques'], 'fr', true, 'Chaque élément chimique possède un spectre unique, permettant d''identifier la composition des étoiles à distance.'),
('sciences', 4, 'Qu''est-ce que la fermentation alcoolique ?', 'La transformation des sucres en éthanol et CO2 par des levures', ARRAY['La distillation de l''alcool', 'L''oxydation de l''alcool', 'La dissolution du sucre dans l''eau'], 'fr', true, 'La fermentation alcoolique est utilisée dans la fabrication du vin, de la bière et du pain.'),
('sciences', 4, 'Quel est le paradoxe EPR en physique quantique ?', 'Un paradoxe remettant en question la complétude de la mécanique quantique via l''intrication', ARRAY['Le paradoxe du chat mort et vivant', 'Le problème de la mesure quantique', 'La dualité onde-particule de la lumière'], 'fr', true, 'Le paradoxe Einstein-Podolsky-Rosen questionne le réalisme local, résolu en faveur de la mécanique quantique par les inégalités de Bell.'),
('sciences', 4, 'Qu''est-ce que l''énergie noire ?', 'Une énergie hypothétique responsable de l''accélération de l''expansion de l''univers', ARRAY['L''énergie contenue dans les trous noirs', 'L''énergie des réactions nucléaires', 'L''énergie de la matière noire'], 'fr', true, 'L''énergie noire représenterait environ 68% du contenu de l''univers.'),
('sciences', 4, 'Qu''est-ce que la PCR (réaction en chaîne par polymérase) ?', 'Une technique pour amplifier un fragment d''ADN spécifique', ARRAY['Un type de réaction nucléaire', 'Une méthode de purification chimique', 'Un test de grossesse'], 'fr', true, 'La PCR, inventée par Kary Mullis, permet de copier des millions de fois un segment d''ADN spécifique.'),
('sciences', 4, 'Comment s''appelle le rayonnement résiduel du Big Bang ?', 'Le fond diffus cosmologique', ARRAY['Le rayonnement Hawking', 'Le spectre solaire', 'Les rayons cosmiques'], 'fr', true, 'Le fond diffus cosmologique (CMB) est un rayonnement micro-onde datant de 380 000 ans après le Big Bang.'),
('sciences', 4, 'Qu''est-ce qu''un prion ?', 'Une protéine mal repliée qui peut transmettre sa forme anormale à d''autres protéines', ARRAY['Un virus très petit', 'Une bactérie résistante', 'Un fragment d''ARN infectieux'], 'fr', true, 'Les prions causent des maladies neurodégénératives comme la maladie de Creutzfeldt-Jakob.'),
('sciences', 4, 'Qu''est-ce que la chimie organométallique ?', 'L''étude des composés contenant des liaisons métal-carbone', ARRAY['La chimie des organismes vivants', 'L''étude des métaux dans le sol', 'La synthèse de médicaments'], 'fr', true, 'La chimie organométallique a des applications en catalyse industrielle et en synthèse de médicaments.'),
('sciences', 4, 'Quel est le principe de l''électrophorèse ?', 'La séparation de molécules selon leur charge et leur taille dans un champ électrique', ARRAY['La mesure du courant électrique dans un liquide', 'La production d''électricité par réaction chimique', 'La diffusion de particules dans un gel'], 'fr', true, 'L''électrophorèse est utilisée pour séparer l''ADN, l''ARN et les protéines en biologie moléculaire.'),
('sciences', 4, 'Qu''est-ce que le principe d''exclusion de Pauli ?', 'Deux fermions ne peuvent pas occuper le même état quantique simultanément', ARRAY['Un électron ne peut pas quitter son orbite', 'Deux atomes ne peuvent pas fusionner', 'La lumière ne peut pas dépasser une certaine vitesse'], 'fr', true, 'Le principe de Pauli explique la structure électronique des atomes et la stabilité de la matière.'),
('sciences', 4, 'Quelle est la fonction de l''appareil de Golgi dans une cellule ?', 'Modifier, trier et emballer les protéines pour leur distribution', ARRAY['Produire de l''énergie', 'Stocker l''ADN', 'Synthétiser les lipides'], 'fr', true, 'L''appareil de Golgi est un organite qui traite et expédie les protéines vers leur destination finale dans ou hors de la cellule.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('sciences', 5, 'Qu''est-ce que la limite de Chandrasekhar ?', 'La masse maximale d''une naine blanche stable (~1,4 masse solaire)', ARRAY['La distance maximale observable dans l''univers', 'La température maximale d''une étoile', 'Le rayon minimal d''un trou noir'], 'fr', true, 'Au-delà de 1,4 masse solaire, une naine blanche s''effondre en étoile à neutrons ou en trou noir.'),
('sciences', 5, 'Qu''est-ce que le théorème de Noether ?', 'Chaque symétrie continue correspond à une loi de conservation', ARRAY['L''énergie est quantifiée', 'L''entropie augmente toujours', 'La vitesse de la lumière est constante'], 'fr', true, 'Emmy Noether a démontré que les symétries de l''espace-temps impliquent la conservation de l''énergie, de la quantité de mouvement, etc.'),
('sciences', 5, 'Qu''est-ce que la décohérence quantique ?', 'La perte des propriétés quantiques d''un système par interaction avec son environnement', ARRAY['La destruction d''une particule quantique', 'La séparation de deux particules intriquées', 'L''effondrement d''une étoile à neutrons'], 'fr', true, 'La décohérence explique pourquoi les effets quantiques ne sont pas observables à l''échelle macroscopique.'),
('sciences', 5, 'Qu''est-ce que la condensation de Bose-Einstein ?', 'Un état de la matière où des bosons se comportent comme une seule entité quantique à très basse température', ARRAY['La fusion de plusieurs atomes en un seul', 'Un nouveau type de supraconducteur', 'La formation de cristaux dans un gaz'], 'fr', true, 'Prédite par Bose et Einstein, cette condensation a été réalisée expérimentalement en 1995 à des températures proches du zéro absolu.'),
('sciences', 5, 'Qu''est-ce que la conjecture de Poincaré ?', 'Toute variété compacte simplement connexe de dimension 3 est homéomorphe à la sphère', ARRAY['Tout nombre pair est somme de deux nombres premiers', 'Il existe une infinité de nombres premiers jumeaux', 'La fonction zêta a tous ses zéros sur la droite critique'], 'fr', true, 'Démontrée par Grigori Perelman en 2003, c''est le seul problème du millénaire résolu à ce jour.'),
('sciences', 5, 'Qu''est-ce que le rayonnement de Hawking ?', 'Un rayonnement théorique émis par les trous noirs dû aux effets quantiques', ARRAY['Le rayonnement du Big Bang', 'Les rayons X émis par les pulsars', 'Le rayonnement des supernovae'], 'fr', true, 'Stephen Hawking a prédit en 1974 que les trous noirs émettent un faible rayonnement thermique et peuvent s''évaporer.'),
('sciences', 5, 'Qu''est-ce que l''équation de Schrödinger ?', 'L''équation fondamentale décrivant l''évolution temporelle d''un système quantique', ARRAY['L''équation reliant masse et énergie', 'L''équation des ondes électromagnétiques', 'L''équation de la gravitation universelle'], 'fr', true, 'L''équation de Schrödinger est à la mécanique quantique ce que les lois de Newton sont à la mécanique classique.'),
('sciences', 5, 'Qu''est-ce que la supersymétrie (SUSY) ?', 'Une théorie proposant un partenaire supersymétrique pour chaque particule du modèle standard', ARRAY['La symétrie parfaite de l''univers', 'L''équivalence entre matière et antimatière', 'La théorie unificatrice de toutes les forces'], 'fr', true, 'La supersymétrie n''a pas encore été confirmée expérimentalement, mais elle résoudrait plusieurs problèmes du modèle standard.'),
('sciences', 5, 'Qu''est-ce que la topologie en mathématiques ?', 'L''étude des propriétés géométriques invariantes par déformation continue', ARRAY['L''étude des surfaces planes', 'La géométrie des fractales', 'L''algèbre des matrices'], 'fr', true, 'En topologie, une tasse et un beignet sont équivalents car on peut déformer l''un en l''autre continûment.'),
('sciences', 5, 'Qu''est-ce que la renormalisation en physique quantique ?', 'Une technique pour éliminer les infinis dans les calculs de théorie quantique des champs', ARRAY['La normalisation des vecteurs quantiques', 'La calibration des instruments de mesure', 'Le rétablissement de la symétrie brisée'], 'fr', true, 'La renormalisation permet d''obtenir des prédictions finies et vérifiables en QED et QCD.'),
('sciences', 5, 'Qu''est-ce que le principe holographique ?', 'L''information contenue dans un volume peut être encodée sur sa surface frontière', ARRAY['L''univers est un hologramme projeté', 'Les trous noirs sont des hologrammes', 'La lumière contient toute l''information sur la matière'], 'fr', true, 'Proposé par t''Hooft et Susskind, ce principe suggère que la physique 3D peut être décrite par une théorie 2D sur la frontière.'),
('sciences', 5, 'Qu''est-ce que la chromodynamique quantique (QCD) ?', 'La théorie de l''interaction forte entre quarks et gluons', ARRAY['La théorie des couleurs en optique quantique', 'L''étude de la lumière dans les semi-conducteurs', 'La théorie des champs électromagnétiques'], 'fr', true, 'La QCD décrit comment les quarks sont liés par les gluons via la charge de couleur pour former protons et neutrons.'),
('sciences', 5, 'Qu''est-ce que le paradoxe de l''information des trous noirs ?', 'Le conflit entre la destruction apparente d''information par un trou noir et la mécanique quantique', ARRAY['L''impossibilité de mesurer la taille d''un trou noir', 'Le fait que la lumière ne peut pas s''échapper', 'Le ralentissement du temps près d''un trou noir'], 'fr', true, 'La mécanique quantique impose la conservation de l''information, mais les trous noirs semblent la détruire.'),
('sciences', 5, 'Qu''est-ce que l''effet Casimir ?', 'Une force attractive entre deux plaques conductrices due aux fluctuations quantiques du vide', ARRAY['La répulsion entre deux aimants supraconducteurs', 'L''attraction entre particules chargées', 'La pression exercée par la lumière'], 'fr', true, 'L''effet Casimir prouve que le vide quantique n''est pas réellement vide mais rempli de fluctuations d''énergie.'),
('sciences', 5, 'Qu''est-ce que la théorie des cordes ?', 'Une théorie où les particules fondamentales sont des cordes vibrantes unidimensionnelles', ARRAY['Une théorie musicale appliquée à la physique', 'Une théorie sur les fils cosmiques', 'Une théorie sur les réseaux neuronaux'], 'fr', true, 'La théorie des cordes tente d''unifier la mécanique quantique et la relativité générale, nécessitant 10 ou 11 dimensions.'),
('sciences', 5, 'Qu''est-ce que l''effet tunnel quantique ?', 'La capacité d''une particule à traverser une barrière d''énergie qu''elle ne pourrait pas franchir classiquement', ARRAY['Le passage de la lumière à travers un trou noir', 'La téléportation de matière', 'La création de particules dans le vide'], 'fr', true, 'L''effet tunnel est essentiel au fonctionnement des semi-conducteurs et à la fusion nucléaire dans les étoiles.'),
('sciences', 5, 'Qu''est-ce que la brisure spontanée de symétrie ?', 'Un phénomène où l''état fondamental d''un système ne possède pas la symétrie des lois physiques', ARRAY['La destruction d''une symétrie par une force externe', 'L''asymétrie naturelle de l''univers', 'La déformation d''un cristal sous pression'], 'fr', true, 'La brisure spontanée de symétrie explique le mécanisme de Higgs et la supraconductivité.'),
('sciences', 5, 'Qu''est-ce que la conjecture de Riemann ?', 'Tous les zéros non triviaux de la fonction zêta ont une partie réelle égale à 1/2', ARRAY['Il existe une infinité de nombres premiers', 'Tout nombre entier se décompose en facteurs premiers', 'La série harmonique diverge'], 'fr', true, 'Non résolue depuis 1859, la conjecture de Riemann est l''un des problèmes du millénaire du Clay Mathematics Institute.'),
('sciences', 5, 'Qu''est-ce que la gravité quantique à boucles ?', 'Une théorie quantifiant l''espace-temps en unités discrètes à l''échelle de Planck', ARRAY['Une théorie de la gravité dans les accélérateurs', 'Un modèle de gravité artificielle', 'La théorie des boucles magnétiques solaires'], 'fr', true, 'Alternative à la théorie des cordes, la gravité quantique à boucles propose que l''espace lui-même est granulaire.'),
('sciences', 5, 'Qu''est-ce que le tenseur de Riemann ?', 'Un objet mathématique décrivant la courbure de l''espace-temps en relativité générale', ARRAY['Un vecteur mesurant la force gravitationnelle', 'Une matrice de transformation quantique', 'Un scalaire décrivant l''énergie noire'], 'fr', true, 'Le tenseur de Riemann est fondamental dans les équations d''Einstein de la relativité générale.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('sciences', 1, 'What is the closest star to Earth?', 'The Sun', ARRAY['Alpha Centauri', 'Sirius', 'Polaris'], 'en', true, 'The Sun is about 150 million km from Earth, making it our closest star.'),
('sciences', 1, 'How many legs does a spider have?', '8', ARRAY['6', '10', '4'], 'en', true, 'Spiders are arachnids and always have 8 legs, unlike insects which have 6.'),
('sciences', 1, 'What gas do humans need to breathe?', 'Oxygen', ARRAY['Carbon dioxide', 'Nitrogen', 'Helium'], 'en', true, 'Humans breathe in oxygen and exhale carbon dioxide.'),
('sciences', 1, 'What is the largest organ of the human body?', 'The skin', ARRAY['The liver', 'The brain', 'The lungs'], 'en', true, 'The skin covers about 2 square meters and weighs around 3.6 kg in adults.'),
('sciences', 1, 'Which planet is known for its rings?', 'Saturn', ARRAY['Jupiter', 'Uranus', 'Neptune'], 'en', true, 'Saturn is famous for its spectacular ring system made of ice and rock particles.'),
('sciences', 1, 'What do bees produce?', 'Honey', ARRAY['Silk', 'Wax only', 'Milk'], 'en', true, 'Bees produce honey from flower nectar, storing it in their hives.'),
('sciences', 1, 'What is H2O commonly known as?', 'Water', ARRAY['Salt', 'Oxygen', 'Hydrogen peroxide'], 'en', true, 'H2O is the chemical formula for water: two hydrogen atoms and one oxygen atom.'),
('sciences', 1, 'Which animal is the tallest on Earth?', 'The giraffe', ARRAY['The elephant', 'The horse', 'The ostrich'], 'en', true, 'Giraffes can reach heights of up to 5.7 meters, making them the tallest living animals.'),
('sciences', 1, 'What causes day and night?', 'The rotation of the Earth', ARRAY['The Moon moving', 'The Sun moving', 'Cloud coverage'], 'en', true, 'Earth rotates on its axis every 24 hours, creating the cycle of day and night.'),
('sciences', 1, 'How many planets are in our solar system?', '8', ARRAY['9', '7', '10'], 'en', true, 'There are 8 planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, and Neptune.'),
('sciences', 1, 'What is the hardest natural substance on Earth?', 'Diamond', ARRAY['Gold', 'Iron', 'Quartz'], 'en', true, 'Diamond scores 10 on the Mohs hardness scale, the maximum possible rating.'),
('sciences', 1, 'Which part of the plant absorbs water?', 'The roots', ARRAY['The leaves', 'The stem', 'The flowers'], 'en', true, 'Roots absorb water and nutrients from the soil through tiny root hairs.'),
('sciences', 1, 'What is the fastest land animal?', 'The cheetah', ARRAY['The lion', 'The horse', 'The wolf'], 'en', true, 'Cheetahs can reach speeds of up to 120 km/h in short bursts.'),
('sciences', 1, 'What do caterpillars turn into?', 'Butterflies or moths', ARRAY['Beetles', 'Dragonflies', 'Bees'], 'en', true, 'Caterpillars undergo metamorphosis inside a chrysalis to become butterflies or moths.'),
('sciences', 1, 'What is the boiling point of water?', '100°C', ARRAY['50°C', '80°C', '120°C'], 'en', true, 'Water boils at 100 degrees Celsius (212°F) at standard atmospheric pressure.'),
('sciences', 1, 'How many seasons are there in a year?', '4', ARRAY['2', '3', '6'], 'en', true, 'The four seasons are spring, summer, autumn, and winter.'),
('sciences', 1, 'What organ pumps blood through the body?', 'The heart', ARRAY['The lungs', 'The liver', 'The kidneys'], 'en', true, 'The heart pumps about 7,500 liters of blood through the body every day.'),
('sciences', 1, 'Are dolphins fish or mammals?', 'Mammals', ARRAY['Fish', 'Reptiles', 'Amphibians'], 'en', true, 'Dolphins are marine mammals that breathe air and nurse their young with milk.'),
('sciences', 1, 'What is the largest ocean on Earth?', 'The Pacific Ocean', ARRAY['The Atlantic Ocean', 'The Indian Ocean', 'The Arctic Ocean'], 'en', true, 'The Pacific Ocean covers about 165 million square kilometers, roughly one-third of Earth''s surface.'),
('sciences', 1, 'What do we call a baby frog?', 'A tadpole', ARRAY['A fry', 'A larva', 'A cub'], 'en', true, 'Tadpoles are aquatic larvae of frogs that breathe through gills before developing lungs.'),
('sciences', 1, 'Which bone protects the brain?', 'The skull', ARRAY['The spine', 'The ribcage', 'The pelvis'], 'en', true, 'The skull is a bony structure that encases and protects the brain from injury.'),
('sciences', 1, 'What makes leaves green?', 'Chlorophyll', ARRAY['Oxygen', 'Water', 'Sunlight'], 'en', true, 'Chlorophyll is a green pigment in plants that absorbs light for photosynthesis.'),
('sciences', 1, 'What is the biggest planet in our solar system?', 'Jupiter', ARRAY['Saturn', 'Neptune', 'Uranus'], 'en', true, 'Jupiter is so large that over 1,300 Earths could fit inside it.'),
('sciences', 1, 'What type of animal is a whale?', 'A mammal', ARRAY['A fish', 'A reptile', 'An amphibian'], 'en', true, 'Whales are marine mammals that breathe air, are warm-blooded, and nurse their young.'),
('sciences', 1, 'How many bones does an adult human have?', '206', ARRAY['106', '306', '186'], 'en', true, 'Adults have 206 bones; babies are born with about 270, which fuse together as they grow.'),
('sciences', 1, 'What is the main food of pandas?', 'Bamboo', ARRAY['Fish', 'Berries', 'Insects'], 'en', true, 'Giant pandas eat almost exclusively bamboo, consuming up to 38 kg per day.'),
('sciences', 1, 'What is a group of stars that forms a pattern called?', 'A constellation', ARRAY['A galaxy', 'A nebula', 'A cluster'], 'en', true, 'Constellations are patterns of stars as seen from Earth, used for navigation for centuries.'),
('sciences', 1, 'What weather phenomenon involves lightning and thunder?', 'A thunderstorm', ARRAY['A blizzard', 'A tornado', 'A heatwave'], 'en', true, 'Thunderstorms produce lightning (electrical discharges) and thunder (the resulting sound waves).'),
('sciences', 1, 'What is ice made of?', 'Frozen water', ARRAY['Frozen air', 'Frozen salt', 'Frozen gas'], 'en', true, 'Ice is water in its solid state, formed when the temperature drops below 0°C.'),
('sciences', 1, 'What carries blood away from the heart?', 'Arteries', ARRAY['Veins', 'Capillaries', 'Nerves'], 'en', true, 'Arteries carry oxygen-rich blood from the heart to the rest of the body.'),
('sciences', 1, 'Where does the Sun rise?', 'In the east', ARRAY['In the west', 'In the north', 'In the south'], 'en', true, 'The Sun appears to rise in the east and set in the west due to Earth''s rotation.'),
('sciences', 1, 'What is the largest mammal on Earth?', 'The blue whale', ARRAY['The elephant', 'The giraffe', 'The hippo'], 'en', true, 'Blue whales can reach 30 meters long and weigh up to 200 tonnes.'),
('sciences', 1, 'How many fingers does a human hand have?', '5', ARRAY['4', '6', '3'], 'en', true, 'Each human hand has 5 fingers: thumb, index, middle, ring, and little finger.'),
('sciences', 1, 'What do plants need to grow?', 'Water, sunlight, and soil', ARRAY['Only water', 'Only sunlight', 'Only soil'], 'en', true, 'Plants need water, sunlight, nutrients from soil, and CO2 to grow through photosynthesis.'),
('sciences', 1, 'What color is the sky on a clear day?', 'Blue', ARRAY['White', 'Green', 'Yellow'], 'en', true, 'The sky appears blue because the atmosphere scatters shorter blue wavelengths of sunlight.'),
('sciences', 1, 'What is the opposite of hot?', 'Cold', ARRAY['Warm', 'Cool', 'Freezing'], 'en', true, 'Hot and cold are opposite sensations related to temperature.'),
('sciences', 1, 'Which sense do our ears provide?', 'Hearing', ARRAY['Sight', 'Smell', 'Taste'], 'en', true, 'Our ears detect sound waves and convert them into signals the brain interprets as hearing.'),
('sciences', 1, 'What are baby cats called?', 'Kittens', ARRAY['Puppies', 'Cubs', 'Foals'], 'en', true, 'Kittens are born blind and deaf, relying entirely on their mother for the first few weeks.'),
('sciences', 1, 'What covers most of the Earth''s surface?', 'Water', ARRAY['Land', 'Ice', 'Sand'], 'en', true, 'About 71% of the Earth''s surface is covered by water, mostly in oceans.'),
('sciences', 1, 'Which is faster: light or sound?', 'Light', ARRAY['Sound', 'They are equal', 'It depends'], 'en', true, 'Light travels at about 300,000 km/s while sound travels at about 340 m/s in air.'),
('sciences', 1, 'What insect makes silk?', 'The silkworm', ARRAY['The spider', 'The bee', 'The ant'], 'en', true, 'Silkworms (Bombyx mori) spin cocoons made of silk thread, used to make silk fabric.'),
('sciences', 1, 'What is the hottest planet in our solar system?', 'Venus', ARRAY['Mercury', 'Mars', 'Jupiter'], 'en', true, 'Despite being farther from the Sun than Mercury, Venus is hottest due to its thick greenhouse atmosphere.'),
('sciences', 1, 'What do snakes use to smell?', 'Their tongue', ARRAY['Their nose', 'Their skin', 'Their eyes'], 'en', true, 'Snakes flick their tongue to collect scent particles and analyze them with Jacobson''s organ.'),
('sciences', 1, 'How many continents are there?', '7', ARRAY['5', '6', '8'], 'en', true, 'The seven continents are Africa, Antarctica, Asia, Australia, Europe, North America, and South America.'),
('sciences', 1, 'What animal carries its home on its back?', 'A snail', ARRAY['A crab', 'A hedgehog', 'A beetle'], 'en', true, 'Snails carry a spiral shell on their back into which they can retract for protection.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('sciences', 2, 'What is the chemical symbol for gold?', 'Au', ARRAY['Go', 'Ag', 'Gd'], 'en', true, 'Au comes from the Latin word Aurum. Gold has atomic number 79.'),
('sciences', 2, 'What is the most abundant gas in Earth''s atmosphere?', 'Nitrogen', ARRAY['Oxygen', 'Carbon dioxide', 'Argon'], 'en', true, 'Nitrogen makes up about 78% of Earth''s atmosphere.'),
('sciences', 2, 'Who developed the theory of relativity?', 'Albert Einstein', ARRAY['Isaac Newton', 'Stephen Hawking', 'Niels Bohr'], 'en', true, 'Albert Einstein published the special theory of relativity in 1905 and general relativity in 1915.'),
('sciences', 2, 'What type of blood cells fight infections?', 'White blood cells', ARRAY['Red blood cells', 'Platelets', 'Plasma'], 'en', true, 'White blood cells (leukocytes) are part of the immune system and fight bacteria, viruses, and other pathogens.'),
('sciences', 2, 'What is the name of our galaxy?', 'The Milky Way', ARRAY['Andromeda', 'Sombrero Galaxy', 'Triangulum'], 'en', true, 'The Milky Way contains 100-400 billion stars and is about 100,000 light-years across.'),
('sciences', 2, 'What vitamin does sunlight help our body produce?', 'Vitamin D', ARRAY['Vitamin C', 'Vitamin A', 'Vitamin B12'], 'en', true, 'UVB radiation from sunlight triggers vitamin D synthesis in the skin.'),
('sciences', 2, 'What is the chemical formula for table salt?', 'NaCl', ARRAY['KCl', 'CaCl2', 'NaOH'], 'en', true, 'Table salt is sodium chloride, composed of sodium and chlorine atoms.'),
('sciences', 2, 'What natural phenomenon is measured on the Richter scale?', 'Earthquakes', ARRAY['Tornadoes', 'Hurricanes', 'Tsunamis'], 'en', true, 'The Richter scale measures the magnitude of seismic waves produced by earthquakes.'),
('sciences', 2, 'What is the liquid metal at room temperature?', 'Mercury', ARRAY['Lead', 'Aluminum', 'Zinc'], 'en', true, 'Mercury is the only metal that is liquid at standard room temperature and pressure.'),
('sciences', 2, 'What part of a cell contains DNA?', 'The nucleus', ARRAY['The cytoplasm', 'The membrane', 'The mitochondria'], 'en', true, 'The nucleus houses the cell''s DNA, which carries genetic instructions for growth and reproduction.'),
('sciences', 2, 'How many teeth does an adult human typically have?', '32', ARRAY['28', '36', '30'], 'en', true, 'Adults have 32 permanent teeth: 8 incisors, 4 canines, 8 premolars, and 12 molars.'),
('sciences', 2, 'What is the study of fossils called?', 'Paleontology', ARRAY['Archaeology', 'Geology', 'Anthropology'], 'en', true, 'Paleontology studies ancient life through fossils to understand evolution and past ecosystems.'),
('sciences', 2, 'What organ filters blood and produces urine?', 'The kidneys', ARRAY['The liver', 'The spleen', 'The pancreas'], 'en', true, 'The kidneys filter about 180 liters of blood daily, producing 1-2 liters of urine.'),
('sciences', 2, 'What is the normal human body temperature?', '37°C (98.6°F)', ARRAY['36°C', '38°C', '39°C'], 'en', true, 'The average human body temperature is approximately 37°C or 98.6°F.'),
('sciences', 2, 'How many chromosomes do human cells have?', '46', ARRAY['23', '48', '44'], 'en', true, 'Human cells contain 46 chromosomes arranged in 23 pairs.'),
('sciences', 2, 'What type of rock is formed from cooled lava?', 'Igneous rock', ARRAY['Sedimentary rock', 'Metamorphic rock', 'Limestone'], 'en', true, 'Igneous rocks form when magma or lava cools and solidifies, such as basalt and granite.'),
('sciences', 2, 'Who invented the first practical vaccine?', 'Edward Jenner', ARRAY['Louis Pasteur', 'Alexander Fleming', 'Robert Koch'], 'en', true, 'Edward Jenner developed the first successful vaccine against smallpox in 1796 using cowpox.'),
('sciences', 2, 'What is a diamond made of?', 'Pure carbon', ARRAY['Silicon', 'Quartz', 'Calcium'], 'en', true, 'Diamonds are made of carbon atoms arranged in a crystal structure under extreme heat and pressure.'),
('sciences', 2, 'How long does Earth take to orbit the Sun?', '365.25 days', ARRAY['30 days', '180 days', '500 days'], 'en', true, 'Earth takes approximately 365.25 days to complete one orbit around the Sun, which is why we have leap years.'),
('sciences', 2, 'What is the main function of red blood cells?', 'Transporting oxygen', ARRAY['Fighting infections', 'Clotting blood', 'Producing hormones'], 'en', true, 'Red blood cells contain hemoglobin, which binds oxygen and carries it to tissues throughout the body.'),
('sciences', 2, 'What is the strongest bone in the human body?', 'The femur', ARRAY['The skull', 'The tibia', 'The spine'], 'en', true, 'The femur (thighbone) is the longest and strongest bone in the human body.'),
('sciences', 2, 'What gas do plants release during photosynthesis?', 'Oxygen', ARRAY['Carbon dioxide', 'Nitrogen', 'Hydrogen'], 'en', true, 'During photosynthesis, plants absorb CO2 and release oxygen as a byproduct.'),
('sciences', 2, 'What is the ozone layer and where is it?', 'A protective layer of O3 in the stratosphere', ARRAY['A cloud layer in the troposphere', 'A gas layer in the mesosphere', 'A radiation belt in the thermosphere'], 'en', true, 'The ozone layer in the stratosphere absorbs most of the Sun''s harmful ultraviolet radiation.'),
('sciences', 2, 'What is the chemical symbol for iron?', 'Fe', ARRAY['Ir', 'In', 'Fr'], 'en', true, 'Fe comes from the Latin word Ferrum. Iron is the most common element on Earth by mass.'),
('sciences', 2, 'What causes tides in the ocean?', 'The gravitational pull of the Moon and Sun', ARRAY['Wind patterns', 'Earth''s rotation', 'Underwater earthquakes'], 'en', true, 'Tides are caused primarily by the Moon''s gravitational attraction on Earth''s water.'),
('sciences', 2, 'What is the study of insects called?', 'Entomology', ARRAY['Zoology', 'Botany', 'Ornithology'], 'en', true, 'Entomology is the scientific study of insects, the most diverse group of animals on Earth.'),
('sciences', 2, 'What is the main component of the Sun?', 'Hydrogen', ARRAY['Helium', 'Carbon', 'Iron'], 'en', true, 'The Sun is composed of about 73% hydrogen and 25% helium by mass.'),
('sciences', 2, 'Which planet is closest to the Sun?', 'Mercury', ARRAY['Venus', 'Mars', 'Earth'], 'en', true, 'Mercury orbits the Sun at an average distance of about 58 million km.'),
('sciences', 2, 'What organ produces bile?', 'The liver', ARRAY['The stomach', 'The pancreas', 'The gallbladder'], 'en', true, 'The liver produces bile, which is stored in the gallbladder and helps digest fats.'),
('sciences', 2, 'What is a fossil?', 'Preserved remains or traces of ancient organisms in rock', ARRAY['A type of mineral', 'A volcanic rock', 'A natural crystal'], 'en', true, 'Fossils form over millions of years as organisms are buried and mineralized in sedimentary rock.'),
('sciences', 2, 'What are animals that are active at night called?', 'Nocturnal', ARRAY['Diurnal', 'Crepuscular', 'Migratory'], 'en', true, 'Nocturnal animals like owls and bats have adapted to be active during nighttime hours.'),
('sciences', 2, 'How many liters of blood does an adult body contain?', 'About 5 liters', ARRAY['About 3 liters', 'About 8 liters', 'About 10 liters'], 'en', true, 'An average adult has approximately 5 liters (about 1.3 gallons) of blood circulating in their body.'),
('sciences', 2, 'What is the largest desert in the world?', 'The Sahara', ARRAY['The Gobi', 'The Atacama', 'The Kalahari'], 'en', true, 'The Sahara Desert covers about 9 million square kilometers in North Africa.'),
('sciences', 2, 'What gas is used in balloons that float?', 'Helium', ARRAY['Hydrogen', 'Nitrogen', 'Oxygen'], 'en', true, 'Helium is lighter than air and non-flammable, making it safe for party balloons.'),
('sciences', 2, 'What is the chemical symbol for copper?', 'Cu', ARRAY['Co', 'Cr', 'Ca'], 'en', true, 'Cu comes from the Latin word Cuprum. Copper is widely used in electrical wiring.'),
('sciences', 2, 'What is the process by which plants make food?', 'Photosynthesis', ARRAY['Respiration', 'Fermentation', 'Digestion'], 'en', true, 'Photosynthesis converts sunlight, water, and CO2 into glucose and oxygen.'),
('sciences', 2, 'Which planet has the most moons?', 'Saturn', ARRAY['Jupiter', 'Uranus', 'Neptune'], 'en', true, 'Saturn has over 140 known moons, the most of any planet in our solar system.'),
('sciences', 2, 'What is the main purpose of the skeleton?', 'To support the body and protect organs', ARRAY['To produce energy', 'To digest food', 'To regulate temperature'], 'en', true, 'The skeleton provides structural support, protects vital organs, and allows movement.'),
('sciences', 2, 'What element has the atomic number 1?', 'Hydrogen', ARRAY['Helium', 'Lithium', 'Carbon'], 'en', true, 'Hydrogen is the simplest and most abundant element in the universe with just one proton.'),
('sciences', 2, 'Who discovered penicillin?', 'Alexander Fleming', ARRAY['Louis Pasteur', 'Marie Curie', 'Robert Koch'], 'en', true, 'Alexander Fleming accidentally discovered penicillin in 1928 from a mold contaminating a petri dish.'),
('sciences', 2, 'What is the smallest continent?', 'Australia/Oceania', ARRAY['Europe', 'Antarctica', 'South America'], 'en', true, 'Australia/Oceania is the smallest continent at about 8.5 million square kilometers.'),
('sciences', 2, 'What is the chemical symbol for silver?', 'Ag', ARRAY['Si', 'Sr', 'Sv'], 'en', true, 'Ag comes from the Latin word Argentum. Silver has atomic number 47.'),
('sciences', 2, 'What is the longest river in the world?', 'The Nile', ARRAY['The Amazon', 'The Mississippi', 'The Yangtze'], 'en', true, 'The Nile stretches approximately 6,650 km through northeastern Africa.'),
('sciences', 2, 'What are herbivores?', 'Animals that eat only plants', ARRAY['Animals that eat only meat', 'Animals that eat everything', 'Animals that eat insects'], 'en', true, 'Herbivores like cows, rabbits, and deer have digestive systems adapted for plant material.'),
('sciences', 2, 'What planet is called the Red Planet?', 'Mars', ARRAY['Venus', 'Jupiter', 'Saturn'], 'en', true, 'Mars appears red because of iron oxide (rust) on its surface.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('sciences', 3, 'What is the unit of electrical resistance?', 'Ohm', ARRAY['Volt', 'Ampere', 'Watt'], 'en', true, 'The Ohm (Ω) measures electrical resistance, named after physicist Georg Simon Ohm.'),
('sciences', 3, 'What is the powerhouse of the cell?', 'The mitochondria', ARRAY['The nucleus', 'The ribosome', 'The Golgi apparatus'], 'en', true, 'Mitochondria generate most of the cell''s energy (ATP) through cellular respiration.'),
('sciences', 3, 'What is the speed of light approximately?', '300,000 km/s', ARRAY['150,000 km/s', '500,000 km/s', '1,000,000 km/s'], 'en', true, 'The speed of light in a vacuum is approximately 299,792 km/s.'),
('sciences', 3, 'What is the pH of a neutral solution?', '7', ARRAY['0', '14', '1'], 'en', true, 'A pH of 7 is neutral; below 7 is acidic and above 7 is basic/alkaline.'),
('sciences', 3, 'Who formulated the three laws of motion?', 'Isaac Newton', ARRAY['Galileo', 'Albert Einstein', 'Johannes Kepler'], 'en', true, 'Newton''s three laws of motion were published in 1687 in the Principia Mathematica.'),
('sciences', 3, 'What is the chemical element with atomic number 6?', 'Carbon', ARRAY['Oxygen', 'Nitrogen', 'Hydrogen'], 'en', true, 'Carbon has 6 protons and is the basis of organic chemistry and all known life.'),
('sciences', 3, 'What is the process of a solid turning directly into gas called?', 'Sublimation', ARRAY['Evaporation', 'Melting', 'Condensation'], 'en', true, 'Sublimation occurs without passing through the liquid phase, like dry ice turning into CO2 gas.'),
('sciences', 3, 'What subatomic particle has a negative charge?', 'The electron', ARRAY['The proton', 'The neutron', 'The quark'], 'en', true, 'Electrons carry a negative charge of -1.6 × 10⁻¹⁹ coulombs.'),
('sciences', 3, 'Who discovered radioactivity?', 'Henri Becquerel', ARRAY['Marie Curie', 'Pierre Curie', 'Ernest Rutherford'], 'en', true, 'Henri Becquerel discovered radioactivity in 1896 while studying phosphorescent uranium salts.'),
('sciences', 3, 'What type of chemical bond involves the sharing of electrons?', 'Covalent bond', ARRAY['Ionic bond', 'Metallic bond', 'Hydrogen bond'], 'en', true, 'In a covalent bond, atoms share electron pairs to achieve stable electron configurations.'),
('sciences', 3, 'What is an isotope?', 'An atom with the same number of protons but different neutrons', ARRAY['A charged atom', 'An atom without electrons', 'A type of molecule'], 'en', true, 'Isotopes of an element have identical atomic numbers but different mass numbers.'),
('sciences', 3, 'What causes the Northern Lights (Aurora Borealis)?', 'Solar particles interacting with Earth''s magnetosphere', ARRAY['Light reflecting off ice', 'Volcanic activity', 'Moonlight refraction'], 'en', true, 'Charged particles from the solar wind excite atmospheric molecules, producing colorful light displays.'),
('sciences', 3, 'What is Avogadro''s number?', '6.022 × 10²³', ARRAY['3.14 × 10⁸', '1.602 × 10⁻¹⁹', '9.81'], 'en', true, 'Avogadro''s number represents the number of particles in one mole of a substance.'),
('sciences', 3, 'Who formulated the laws of heredity?', 'Gregor Mendel', ARRAY['Charles Darwin', 'Louis Pasteur', 'James Watson'], 'en', true, 'Gregor Mendel discovered the laws of inheritance through experiments with pea plants in the 1860s.'),
('sciences', 3, 'What is the largest bone in the human body?', 'The femur', ARRAY['The tibia', 'The humerus', 'The fibula'], 'en', true, 'The femur (thighbone) is the longest, heaviest, and strongest bone in the human body.'),
('sciences', 3, 'What is the Doppler effect?', 'The change in frequency of a wave when the source moves relative to the observer', ARRAY['The bending of light by gravity', 'The absorption of light by gas', 'The scattering of light in atmosphere'], 'en', true, 'The Doppler effect explains why an ambulance siren changes pitch as it passes by.'),
('sciences', 3, 'How many elements are in the periodic table?', '118', ARRAY['92', '108', '126'], 'en', true, 'The periodic table currently contains 118 confirmed elements, from hydrogen (1) to oganesson (118).'),
('sciences', 3, 'What is the greenhouse effect?', 'The trapping of heat in the atmosphere by certain gases', ARRAY['The destruction of the ozone layer', 'The heating of soil by sunlight', 'The reflection of light by glaciers'], 'en', true, 'The greenhouse effect is a natural process amplified by human emissions of CO2 and methane.'),
('sciences', 3, 'Who discovered the structure of DNA?', 'Watson and Crick', ARRAY['Mendel and Darwin', 'Pasteur and Koch', 'Curie and Rutherford'], 'en', true, 'James Watson and Francis Crick described DNA''s double helix structure in 1953, aided by Rosalind Franklin''s X-ray data.'),
('sciences', 3, 'What is the role of hemoglobin?', 'Transporting oxygen in the blood', ARRAY['Clotting the blood', 'Fighting infections', 'Regulating blood sugar'], 'en', true, 'Hemoglobin is a protein in red blood cells that binds oxygen for transport throughout the body.'),
('sciences', 3, 'What does the Mohs scale measure?', 'The hardness of minerals', ARRAY['The acidity of solutions', 'The strength of earthquakes', 'The brightness of stars'], 'en', true, 'The Mohs scale ranks minerals from 1 (talc, softest) to 10 (diamond, hardest).'),
('sciences', 3, 'What is a light-year?', 'The distance light travels in one year', ARRAY['The time light takes to reach Earth', 'A unit of time', 'The duration of one Earth orbit'], 'en', true, 'One light-year equals approximately 9.461 trillion kilometers.'),
('sciences', 3, 'What is Newton''s third law?', 'For every action, there is an equal and opposite reaction', ARRAY['F = ma', 'An object at rest stays at rest', 'Energy is conserved'], 'en', true, 'Newton''s third law states that forces always come in equal and opposite pairs.'),
('sciences', 3, 'What is the most abundant element in the universe?', 'Hydrogen', ARRAY['Helium', 'Oxygen', 'Carbon'], 'en', true, 'Hydrogen makes up about 75% of all visible matter in the universe.'),
('sciences', 3, 'What is the chemical formula for glucose?', 'C₆H₁₂O₆', ARRAY['C₂H₅OH', 'CH₄', 'C₁₂H₂₂O₁₁'], 'en', true, 'Glucose is a simple sugar and the primary energy source for cells.'),
('sciences', 3, 'What organ is the largest internal organ in the human body?', 'The liver', ARRAY['The lungs', 'The stomach', 'The brain'], 'en', true, 'The liver weighs about 1.5 kg and performs over 500 metabolic functions.'),
('sciences', 3, 'What theory explains the movement of continents?', 'Plate tectonics', ARRAY['Theory of relativity', 'Big Bang theory', 'Theory of evolution'], 'en', true, 'Plate tectonics explains how Earth''s continents move on lithospheric plates over millions of years.'),
('sciences', 3, 'What is the stress hormone called?', 'Cortisol', ARRAY['Adrenaline', 'Insulin', 'Melatonin'], 'en', true, 'Cortisol, produced by the adrenal glands, is often called the stress hormone.'),
('sciences', 3, 'What cellular organelle is responsible for protein synthesis?', 'The ribosome', ARRAY['The mitochondria', 'The lysosome', 'The Golgi apparatus'], 'en', true, 'Ribosomes translate messenger RNA (mRNA) into proteins.'),
('sciences', 3, 'What is the main cause of the dinosaurs'' extinction?', 'An asteroid impact 66 million years ago', ARRAY['A volcanic eruption', 'Slow climate change', 'An epidemic'], 'en', true, 'A 10 km asteroid struck what is now the Yucatan Peninsula, causing a mass extinction event.'),
('sciences', 3, 'What is an ecosystem?', 'A community of living organisms interacting with their physical environment', ARRAY['A type of tropical forest', 'A food chain', 'An animal habitat'], 'en', true, 'Ecosystems include both biotic (living) and abiotic (non-living) components interacting together.'),
('sciences', 3, 'What is the difference between mitosis and meiosis?', 'Meiosis produces cells with half the chromosomes for reproduction', ARRAY['Mitosis is faster', 'Meiosis only occurs in plants', 'They are the same process'], 'en', true, 'Mitosis produces 2 identical cells; meiosis produces 4 cells with half the chromosomes for sexual reproduction.'),
('sciences', 3, 'What type of UV radiation is the most dangerous?', 'UV-C', ARRAY['UV-A', 'UV-B', 'Infrared'], 'en', true, 'UV-C has the most energy and is most harmful, but is fortunately absorbed by the ozone layer.'),
('sciences', 3, 'How do bacteria reproduce?', 'Binary fission', ARRAY['Mitosis', 'Meiosis', 'Budding'], 'en', true, 'In binary fission, a bacterium divides into two identical daughter cells.'),
('sciences', 3, 'What is antibiotic resistance?', 'When bacteria evolve to survive antibiotic treatment', ARRAY['When viruses mutate', 'An immune deficiency', 'An allergic reaction to medicine'], 'en', true, 'Antibiotic resistance is a major public health threat caused by overuse and misuse of antibiotics.'),
('sciences', 3, 'What is the biosphere?', 'All ecosystems on Earth where life exists', ARRAY['Earth''s atmosphere', 'Earth''s core', 'The ozone layer'], 'en', true, 'The biosphere encompasses all environments where living organisms exist, from ocean depths to mountaintops.'),
('sciences', 3, 'What is the role of the diaphragm in breathing?', 'It contracts to allow air into the lungs', ARRAY['It filters air', 'It produces mucus', 'It warms the air'], 'en', true, 'The diaphragm is a muscle that contracts to increase lung volume, drawing air in during inhalation.'),
('sciences', 3, 'What is the atomic number of carbon?', '6', ARRAY['8', '12', '14'], 'en', true, 'Carbon has 6 protons in its nucleus, giving it atomic number 6.'),
('sciences', 3, 'What are prokaryotes?', 'Single-celled organisms without a defined nucleus', ARRAY['Multi-celled organisms', 'Viruses', 'Fungi'], 'en', true, 'Prokaryotes include bacteria and archaea, which lack membrane-bound nuclei.'),
('sciences', 3, 'What is the bond type in a water molecule (H₂O)?', 'Polar covalent bond', ARRAY['Ionic bond', 'Metallic bond', 'Nonpolar covalent bond'], 'en', true, 'The hydrogen and oxygen atoms share electrons unequally, creating a polar covalent bond.'),
('sciences', 3, 'What particle mediates the electromagnetic force?', 'The photon', ARRAY['The electron', 'The gluon', 'The graviton'], 'en', true, 'Photons are the force carriers of the electromagnetic interaction, including visible light.'),
('sciences', 3, 'What is the first law of thermodynamics?', 'Energy cannot be created or destroyed, only transformed', ARRAY['Entropy always increases', 'Heat flows from hot to cold', 'At absolute zero, entropy is zero'], 'en', true, 'The first law of thermodynamics states that the total energy of an isolated system remains constant.'),
('sciences', 3, 'What is the function of the Golgi apparatus?', 'To modify, sort, and package proteins for distribution', ARRAY['To produce energy', 'To store DNA', 'To synthesize lipids'], 'en', true, 'The Golgi apparatus processes and ships proteins to their final destinations inside or outside the cell.'),
('sciences', 3, 'Which planet has the largest known volcano?', 'Mars', ARRAY['Venus', 'Jupiter', 'Earth'], 'en', true, 'Olympus Mons on Mars is the largest known volcano in the solar system at about 21 km high.'),
('sciences', 3, 'What is dispersion in optics?', 'The separation of white light into its component colors', ARRAY['The bending of light', 'The reflection of light', 'The absorption of light'], 'en', true, 'Dispersion occurs when a prism separates white light into the visible spectrum of colors.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('sciences', 4, 'What is Heisenberg''s uncertainty principle?', 'You cannot simultaneously know the exact position and momentum of a particle', ARRAY['Energy cannot be created or destroyed', 'Light is both a wave and particle', 'Every measurement disturbs the system'], 'en', true, 'Heisenberg''s principle sets a fundamental limit on how precisely position and momentum can be known simultaneously.'),
('sciences', 4, 'What is the Higgs boson?', 'The particle responsible for giving mass to other particles', ARRAY['The particle that carries gravity', 'The smallest known particle', 'The particle that binds quarks'], 'en', true, 'The Higgs boson was discovered at CERN in 2012 and confirms the existence of the Higgs field.'),
('sciences', 4, 'What is entropy in thermodynamics?', 'A measure of disorder in a system', ARRAY['A measure of temperature', 'The amount of free energy', 'The internal pressure of a gas'], 'en', true, 'The second law of thermodynamics states that entropy in a closed system tends to increase over time.'),
('sciences', 4, 'What is dark matter?', 'Hypothetical invisible matter that does not emit light', ARRAY['Very dense matter at the center of black holes', 'Interstellar dust particles', 'Antimatter'], 'en', true, 'Dark matter accounts for about 27% of the universe but cannot be directly observed.'),
('sciences', 4, 'What is CRISPR-Cas9?', 'A gene-editing tool', ARRAY['A type of microscope', 'An mRNA vaccine', 'A DNA sequencing algorithm'], 'en', true, 'CRISPR-Cas9 allows precise cutting and modification of DNA, revolutionizing molecular biology.'),
('sciences', 4, 'What is quantum entanglement?', 'A phenomenon where two particles remain correlated regardless of distance', ARRAY['The fusion of two atoms', 'The attraction between electrons', 'A type of chemical bond'], 'en', true, 'Quantum entanglement was called "spooky action at a distance" by Einstein and has been confirmed experimentally.'),
('sciences', 4, 'What is the photoelectric effect?', 'The emission of electrons from a material when hit by light', ARRAY['The production of light by electric current', 'The conversion of heat to electricity', 'The fluorescence of materials'], 'en', true, 'Einstein won the 1921 Nobel Prize for explaining the photoelectric effect, proving light''s particle nature.'),
('sciences', 4, 'What is apoptosis?', 'Programmed cell death', ARRAY['Accelerated cell division', 'Cell fusion', 'Spontaneous genetic mutation'], 'en', true, 'Apoptosis is essential for normal development and the elimination of damaged or unnecessary cells.'),
('sciences', 4, 'What is wave-particle duality?', 'The concept that light and matter exhibit both wave and particle properties', ARRAY['The idea that waves are made of particles', 'The transformation of a wave into a particle', 'The annihilation of waves and particles'], 'en', true, 'Louis de Broglie showed that every particle has an associated wavelength, confirmed by electron diffraction.'),
('sciences', 4, 'What is a quasar?', 'An extremely luminous galactic nucleus powered by a supermassive black hole', ARRAY['A rapidly rotating neutron star', 'A type of supernova', 'A cluster of galaxies'], 'en', true, 'Quasars are the most luminous objects in the universe, visible across billions of light-years.'),
('sciences', 4, 'What is superconductivity?', 'The complete disappearance of electrical resistance at very low temperatures', ARRAY['Maximum thermal conductivity', 'A type of semiconductor', 'Conductivity in vacuum'], 'en', true, 'Superconductors have zero electrical resistance below a critical temperature.'),
('sciences', 4, 'What is the Roche limit?', 'The minimum distance at which a satellite can orbit without being torn apart by tidal forces', ARRAY['The maximum mass of a neutron star', 'The radius of a black hole', 'The minimum Earth-Moon distance'], 'en', true, 'Within the Roche limit, tidal forces from the primary body will disintegrate the satellite.'),
('sciences', 4, 'What is bioluminescence?', 'A chemical reaction producing light in living organisms', ARRAY['Reflection of light by scales', 'Absorption and re-emission of photons', 'Natural phosphorescence'], 'en', true, 'Bioluminescence involves luciferin and luciferase, found in fireflies, deep-sea fish, and jellyfish.'),
('sciences', 4, 'What is PCR (Polymerase Chain Reaction)?', 'A technique to amplify a specific DNA fragment', ARRAY['A type of nuclear reaction', 'A chemical purification method', 'A pregnancy test'], 'en', true, 'PCR, invented by Kary Mullis, can make millions of copies of a specific DNA segment.'),
('sciences', 4, 'What is special relativity in one sentence?', 'The laws of physics are the same for all observers in uniform motion', ARRAY['Space and time are absolute', 'Gravity curves spacetime', 'Mass can only convert to energy'], 'en', true, 'Einstein''s special relativity (1905) unifies space and time and gives us E=mc².'),
('sciences', 4, 'What is dark energy?', 'Hypothetical energy responsible for the accelerating expansion of the universe', ARRAY['Energy contained in black holes', 'Nuclear reaction energy', 'Dark matter energy'], 'en', true, 'Dark energy is estimated to make up about 68% of the total content of the universe.'),
('sciences', 4, 'What is the cosmic microwave background?', 'Residual radiation from the Big Bang', ARRAY['Hawking radiation', 'The solar spectrum', 'Cosmic rays'], 'en', true, 'The CMB is microwave radiation dating to about 380,000 years after the Big Bang, at about 2.7 K.'),
('sciences', 4, 'What is a prion?', 'A misfolded protein that can transmit its abnormal shape to other proteins', ARRAY['A very small virus', 'A resistant bacterium', 'An infectious RNA fragment'], 'en', true, 'Prions cause neurodegenerative diseases like Creutzfeldt-Jakob disease and mad cow disease.'),
('sciences', 4, 'What is spectroscopy?', 'Analyzing light emitted or absorbed by matter to determine its composition', ARRAY['Measuring the speed of light', 'Observing stars with a telescope', 'Calculating astronomical distances'], 'en', true, 'Each chemical element has a unique spectrum, allowing identification of stellar compositions from a distance.'),
('sciences', 4, 'What is the Pauli exclusion principle?', 'Two fermions cannot occupy the same quantum state simultaneously', ARRAY['An electron cannot leave its orbit', 'Two atoms cannot fuse', 'Light cannot exceed a certain speed'], 'en', true, 'The Pauli exclusion principle explains atomic electron structure and the stability of matter.'),
('sciences', 4, 'What is enzymatic catalysis?', 'The acceleration of a chemical reaction by an enzyme without being consumed', ARRAY['The production of enzymes by cells', 'The degradation of proteins', 'DNA synthesis'], 'en', true, 'Enzymes can speed up chemical reactions by factors of 10⁶ to 10¹² compared to uncatalyzed reactions.'),
('sciences', 4, 'What is the EPR paradox?', 'A thought experiment questioning the completeness of quantum mechanics through entanglement', ARRAY['The paradox of the dead-and-alive cat', 'The measurement problem in quantum physics', 'The wave-particle duality of light'], 'en', true, 'The Einstein-Podolsky-Rosen paradox questions local realism, resolved in favor of quantum mechanics by Bell''s inequalities.'),
('sciences', 4, 'What is electrophoresis?', 'Separating molecules by charge and size in an electric field', ARRAY['Measuring electric current in liquid', 'Generating electricity by chemical reaction', 'Diffusing particles through a gel'], 'en', true, 'Electrophoresis is used to separate DNA, RNA, and proteins in molecular biology.'),
('sciences', 4, 'What is the role of telomerase?', 'To extend telomeres to protect DNA during cell division', ARRAY['To cut damaged DNA', 'To transcribe RNA into protein', 'To replicate viruses'], 'en', true, 'Telomerase is linked to cellular aging and cancer research.'),
('sciences', 4, 'What is alcoholic fermentation?', 'The conversion of sugars into ethanol and CO2 by yeast', ARRAY['The distillation of alcohol', 'The oxidation of alcohol', 'The dissolution of sugar in water'], 'en', true, 'Alcoholic fermentation is used in making wine, beer, and bread.'),
('sciences', 4, 'What is the function of the Golgi apparatus in detail?', 'It modifies, sorts, and packages proteins and lipids for transport', ARRAY['It produces cellular energy', 'It stores genetic information', 'It breaks down waste materials'], 'en', true, 'The Golgi apparatus processes proteins from the ER and directs them to their final cellular destinations.'),
('sciences', 4, 'What is gel electrophoresis used for?', 'Separating DNA fragments by size', ARRAY['Amplifying DNA', 'Sequencing genomes', 'Synthesizing proteins'], 'en', true, 'Gel electrophoresis uses an electric field to move DNA fragments through a gel matrix, separating them by size.'),
('sciences', 4, 'What is the difference between a conductor and an insulator?', 'Conductors allow free electron flow while insulators resist it', ARRAY['Conductors are metals and insulators are plastics', 'Conductors are hot and insulators are cold', 'There is no fundamental difference'], 'en', true, 'In conductors, electrons move freely through the material; in insulators, electrons are tightly bound to atoms.'),
('sciences', 4, 'What is an exoplanet?', 'A planet orbiting a star outside our solar system', ARRAY['A dwarf planet in our solar system', 'A moon of Jupiter', 'An asteroid in the Kuiper belt'], 'en', true, 'Thousands of exoplanets have been discovered, some in the habitable zone of their stars.'),
('sciences', 4, 'What is the principle behind nuclear fusion?', 'Combining light atomic nuclei to form heavier ones, releasing energy', ARRAY['Splitting heavy atoms into lighter ones', 'Converting matter into antimatter', 'Accelerating particles to light speed'], 'en', true, 'Nuclear fusion powers the Sun and stars, fusing hydrogen into helium at extreme temperatures and pressures.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('sciences', 5, 'What is the Chandrasekhar limit?', 'The maximum mass of a stable white dwarf star (~1.4 solar masses)', ARRAY['The maximum observable distance in the universe', 'The maximum temperature of a star', 'The minimum radius of a black hole'], 'en', true, 'Beyond 1.4 solar masses, a white dwarf collapses into a neutron star or black hole.'),
('sciences', 5, 'What is Noether''s theorem?', 'Every continuous symmetry corresponds to a conservation law', ARRAY['Energy is quantized', 'Entropy always increases', 'The speed of light is constant'], 'en', true, 'Emmy Noether proved that symmetries of spacetime imply conservation of energy, momentum, and angular momentum.'),
('sciences', 5, 'What is quantum decoherence?', 'The loss of quantum properties through interaction with the environment', ARRAY['The destruction of a quantum particle', 'The separation of entangled particles', 'The collapse of a neutron star'], 'en', true, 'Decoherence explains why quantum effects are not observable at macroscopic scales.'),
('sciences', 5, 'What is a Bose-Einstein condensate?', 'A state of matter where bosons behave as a single quantum entity at near-zero temperature', ARRAY['The fusion of multiple atoms into one', 'A new type of superconductor', 'Crystal formation in a gas'], 'en', true, 'Predicted by Bose and Einstein, this state was first achieved experimentally in 1995 near absolute zero.'),
('sciences', 5, 'What is Hawking radiation?', 'Theoretical radiation emitted by black holes due to quantum effects', ARRAY['Radiation from the Big Bang', 'X-rays from pulsars', 'Radiation from supernovae'], 'en', true, 'Stephen Hawking predicted in 1974 that black holes emit faint thermal radiation and can eventually evaporate.'),
('sciences', 5, 'What is the Schrödinger equation?', 'The fundamental equation describing the time evolution of a quantum system', ARRAY['The equation relating mass and energy', 'The equation for electromagnetic waves', 'The equation of universal gravitation'], 'en', true, 'The Schrödinger equation is to quantum mechanics what Newton''s laws are to classical mechanics.'),
('sciences', 5, 'What is supersymmetry (SUSY)?', 'A theory proposing a supersymmetric partner for each Standard Model particle', ARRAY['The perfect symmetry of the universe', 'The equivalence of matter and antimatter', 'The unifying theory of all forces'], 'en', true, 'Supersymmetry has not been experimentally confirmed but would solve several problems in the Standard Model.'),
('sciences', 5, 'What is the holographic principle?', 'Information in a volume can be encoded on its boundary surface', ARRAY['The universe is a projected hologram', 'Black holes are holograms', 'Light contains all information about matter'], 'en', true, 'Proposed by ''t Hooft and Susskind, it suggests 3D physics can be described by a 2D theory on the boundary.'),
('sciences', 5, 'What is quantum chromodynamics (QCD)?', 'The theory of the strong interaction between quarks and gluons', ARRAY['The theory of colors in quantum optics', 'The study of light in semiconductors', 'The theory of electromagnetic fields'], 'en', true, 'QCD describes how quarks are bound by gluons via color charge to form protons and neutrons.'),
('sciences', 5, 'What is the black hole information paradox?', 'The conflict between information destruction by black holes and quantum mechanics', ARRAY['The impossibility of measuring black hole size', 'The fact that light cannot escape', 'Time slowing near a black hole'], 'en', true, 'Quantum mechanics requires information conservation, but black holes appear to destroy it.'),
('sciences', 5, 'What is the Casimir effect?', 'An attractive force between two conducting plates due to quantum vacuum fluctuations', ARRAY['Repulsion between superconducting magnets', 'Attraction between charged particles', 'Pressure exerted by light'], 'en', true, 'The Casimir effect demonstrates that the quantum vacuum is not truly empty but filled with energy fluctuations.'),
('sciences', 5, 'What is string theory?', 'A theory where fundamental particles are one-dimensional vibrating strings', ARRAY['A musical theory applied to physics', 'A theory about cosmic filaments', 'A theory about neural networks'], 'en', true, 'String theory attempts to unify quantum mechanics and general relativity, requiring 10 or 11 dimensions.'),
('sciences', 5, 'What is quantum tunneling?', 'A particle''s ability to pass through an energy barrier it classically could not', ARRAY['Light passing through a black hole', 'Teleportation of matter', 'Creation of particles from vacuum'], 'en', true, 'Quantum tunneling is essential for semiconductor devices and nuclear fusion in stars.'),
('sciences', 5, 'What is spontaneous symmetry breaking?', 'When the ground state of a system does not share the symmetry of the physical laws', ARRAY['Destruction of symmetry by an external force', 'The natural asymmetry of the universe', 'Deformation of a crystal under pressure'], 'en', true, 'Spontaneous symmetry breaking explains the Higgs mechanism and superconductivity.'),
('sciences', 5, 'What is the Riemann hypothesis?', 'All non-trivial zeros of the zeta function have real part equal to 1/2', ARRAY['There are infinitely many prime numbers', 'Every integer has a unique prime factorization', 'The harmonic series diverges'], 'en', true, 'Unsolved since 1859, the Riemann hypothesis is one of the Clay Mathematics Institute''s Millennium Problems.'),
('sciences', 5, 'What is loop quantum gravity?', 'A theory quantizing spacetime into discrete units at the Planck scale', ARRAY['A theory of gravity in accelerators', 'A model of artificial gravity', 'The theory of solar magnetic loops'], 'en', true, 'As an alternative to string theory, loop quantum gravity proposes that space itself is granular.'),
('sciences', 5, 'What is renormalization in quantum field theory?', 'A technique to remove infinities from calculations in quantum field theory', ARRAY['The normalization of quantum vectors', 'The calibration of measurement instruments', 'The restoration of broken symmetry'], 'en', true, 'Renormalization yields finite, verifiable predictions in QED and QCD.'),
('sciences', 5, 'What is the Poincaré conjecture?', 'Every simply connected compact 3-manifold is homeomorphic to the 3-sphere', ARRAY['Every even number is the sum of two primes', 'There are infinitely many twin primes', 'The zeta function has all zeros on the critical line'], 'en', true, 'Proved by Grigori Perelman in 2003, it is the only solved Millennium Prize Problem.'),
('sciences', 5, 'What is the Riemann tensor?', 'A mathematical object describing the curvature of spacetime in general relativity', ARRAY['A vector measuring gravitational force', 'A quantum transformation matrix', 'A scalar describing dark energy'], 'en', true, 'The Riemann curvature tensor is fundamental to Einstein''s field equations of general relativity.'),
('sciences', 5, 'What is topological quantum computing?', 'A computing approach using anyons and topological properties to perform error-resistant quantum operations', ARRAY['Quantum computing using topological insulators', 'A classical algorithm for topology problems', 'A method to visualize quantum states'], 'en', true, 'Topological quantum computing uses braiding of anyons, potentially more resistant to decoherence than other approaches.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('technologie', 1, 'Que signifie le sigle "Wi-Fi" ?', 'Wireless Fidelity', ARRAY['Wired Fidelity', 'Wide Frequency', 'Web Interface'], 'fr', true, 'Wi-Fi est une marque déposée permettant la connexion sans fil à Internet.'),
('technologie', 1, 'Quel est le nom du système d''exploitation d''Apple pour iPhone ?', 'iOS', ARRAY['Android', 'Windows Phone', 'HarmonyOS'], 'fr', true, 'iOS est le système d''exploitation mobile développé exclusivement par Apple pour ses iPhone.'),
('technologie', 1, 'Quelle touche du clavier permet d''effacer le caractère précédent ?', 'Retour arrière (Backspace)', ARRAY['Entrée', 'Tabulation', 'Supprimer'], 'fr', true, 'La touche Backspace efface le caractère situé avant le curseur.'),
('technologie', 1, 'Comment appelle-t-on un logiciel malveillant ?', 'Un malware', ARRAY['Un hardware', 'Un firmware', 'Un shareware'], 'fr', true, 'Le terme malware désigne tout logiciel conçu pour endommager un système informatique.'),
('technologie', 1, 'Quelle entreprise a créé la console Nintendo Switch ?', 'Nintendo', ARRAY['Sony', 'Microsoft', 'Sega'], 'fr', true, 'La Nintendo Switch est sortie en mars 2017 et se distingue par son mode portable et console.'),
('technologie', 1, 'Quel est le format le plus courant pour les vidéos sur Internet ?', 'MP4', ARRAY['AVI', 'WMV', 'FLV'], 'fr', true, 'Le format MP4 est le standard le plus répandu pour la vidéo en ligne grâce à sa bonne compression.'),
('technologie', 1, 'Que signifie "GPS" ?', 'Global Positioning System', ARRAY['General Position Service', 'Geographic Placement System', 'Global Protocol Standard'], 'fr', true, 'Le GPS utilise des satellites pour déterminer la position géographique d''un appareil.'),
('technologie', 1, 'Quel type de fichier a l''extension ".pdf" ?', 'Un document portable', ARRAY['Une image', 'Une vidéo', 'Un fichier audio'], 'fr', true, 'PDF signifie Portable Document Format, créé par Adobe en 1993.'),
('technologie', 1, 'Quel est le symbole @ utilisé dans les adresses email ?', 'Arobase', ARRAY['Hashtag', 'Dièse', 'Astérisque'], 'fr', true, 'L''arobase (@) sépare le nom d''utilisateur du nom de domaine dans une adresse email.'),
('technologie', 1, 'Quel réseau social est connu pour ses messages courts appelés "tweets" ?', 'Twitter (X)', ARRAY['Facebook', 'Instagram', 'TikTok'], 'fr', true, 'Twitter, renommé X en 2023, est célèbre pour ses messages courts limités en caractères.'),
('technologie', 1, 'Comment appelle-t-on l''écran tactile d''un smartphone ?', 'Un écran tactile', ARRAY['Un écran plasma', 'Un écran cathodique', 'Un écran à cristaux liquides'], 'fr', true, 'Les écrans tactiles détectent le contact des doigts grâce à la technologie capacitive.'),
('technologie', 1, 'Quelle est la fonction principale d''un moteur de recherche ?', 'Trouver des informations sur Internet', ARRAY['Envoyer des emails', 'Stocker des fichiers', 'Créer des sites web'], 'fr', true, 'Les moteurs de recherche comme Google indexent et classent les pages web pour les utilisateurs.'),
('technologie', 1, 'Comment s''appelle le petit programme sur un smartphone ?', 'Une application (app)', ARRAY['Un plugin', 'Un widget', 'Un driver'], 'fr', true, 'Les applications mobiles sont téléchargeables depuis l''App Store ou le Google Play Store.'),
('technologie', 1, 'Quelle entreprise fabrique les ordinateurs Mac ?', 'Apple', ARRAY['Microsoft', 'Dell', 'HP'], 'fr', true, 'Apple conçoit et fabrique les ordinateurs Mac depuis 1984.'),
('technologie', 1, 'Que signifie "USB" ?', 'Universal Serial Bus', ARRAY['Ultra Speed Buffer', 'United System Board', 'Unified Storage Base'], 'fr', true, 'L''USB est un standard de connectique pour le transfert de données et l''alimentation électrique.'),
('technologie', 1, 'Quel appareil permet d''imprimer des documents depuis un ordinateur ?', 'Une imprimante', ARRAY['Un scanner', 'Un projecteur', 'Un routeur'], 'fr', true, 'Les imprimantes reproduisent sur papier des documents numériques, en jet d''encre ou laser.'),
('technologie', 1, 'Quel est le navigateur web développé par Mozilla ?', 'Firefox', ARRAY['Chrome', 'Safari', 'Edge'], 'fr', true, 'Mozilla Firefox est un navigateur open source lancé en 2004.'),
('technologie', 1, 'Comment s''appelle la mémoire vive d''un ordinateur ?', 'RAM', ARRAY['ROM', 'SSD', 'GPU'], 'fr', true, 'La RAM (Random Access Memory) stocke temporairement les données en cours d''utilisation.'),
('technologie', 1, 'Quel service permet d''écouter de la musique en streaming ?', 'Spotify', ARRAY['Google Docs', 'Dropbox', 'Trello'], 'fr', true, 'Spotify est un service de streaming musical fondé en Suède en 2006.'),
('technologie', 1, 'Qu''est-ce qu''un emoji ?', 'Un petit pictogramme utilisé dans les messages', ARRAY['Un virus informatique', 'Un type de fichier', 'Un langage de programmation'], 'fr', true, 'Les emojis sont nés au Japon à la fin des années 1990 et sont devenus un standard Unicode.'),
('technologie', 1, 'Quelle entreprise a créé le réseau social Facebook ?', 'Meta (Mark Zuckerberg)', ARRAY['Google', 'Apple', 'Amazon'], 'fr', true, 'Facebook a été créé par Mark Zuckerberg en 2004 à Harvard. L''entreprise s''appelle désormais Meta.'),
('technologie', 1, 'Que permet de faire un QR code ?', 'Accéder à un contenu en le scannant avec un smartphone', ARRAY['Protéger un fichier', 'Envoyer un email', 'Créer un mot de passe'], 'fr', true, 'Le QR code (Quick Response) peut encoder des URL, du texte ou des informations de contact.'),
('technologie', 1, 'Comment appelle-t-on un ordinateur portable ?', 'Un laptop', ARRAY['Un desktop', 'Un serveur', 'Un mainframe'], 'fr', true, 'Le laptop (ou PC portable) est un ordinateur conçu pour être transporté facilement.'),
('technologie', 1, 'Quel est le plus grand site de vente en ligne au monde ?', 'Amazon', ARRAY['eBay', 'Alibaba', 'Walmart'], 'fr', true, 'Amazon, fondé par Jeff Bezos en 1994, est le leader mondial du commerce en ligne.'),
('technologie', 1, 'Que signifie le "www" dans une adresse web ?', 'World Wide Web', ARRAY['Wide World Web', 'Web Wide World', 'World Web Wide'], 'fr', true, 'Le World Wide Web a été inventé par Tim Berners-Lee au CERN en 1989.'),
('technologie', 1, 'Quel est l''appareil qui distribue la connexion Internet dans une maison ?', 'Un routeur (box Internet)', ARRAY['Un modem uniquement', 'Un switch', 'Un serveur'], 'fr', true, 'Le routeur (souvent intégré dans la box Internet) distribue la connexion aux appareils du foyer.'),
('technologie', 1, 'Quelle application de messagerie utilise un logo vert avec un téléphone blanc ?', 'WhatsApp', ARRAY['Telegram', 'Signal', 'Viber'], 'fr', true, 'WhatsApp, racheté par Facebook (Meta) en 2014, est l''app de messagerie la plus utilisée au monde.'),
('technologie', 1, 'Comment appelle-t-on la protection par mot de passe d''un appareil ?', 'Un verrouillage', ARRAY['Un cryptage', 'Un formatage', 'Un débogage'], 'fr', true, 'Le verrouillage par mot de passe, code PIN ou biométrie protège l''accès à un appareil.'),
('technologie', 1, 'Quel est le nom du service de streaming vidéo d''Amazon ?', 'Prime Video', ARRAY['Amazon TV', 'Fire TV', 'Amazon Stream'], 'fr', true, 'Amazon Prime Video est un service de streaming inclus dans l''abonnement Amazon Prime.'),
('technologie', 1, 'Que fait la touche "Ctrl+C" sur un clavier ?', 'Copier', ARRAY['Coller', 'Couper', 'Annuler'], 'fr', true, 'Le raccourci Ctrl+C copie l''élément sélectionné dans le presse-papiers.'),
('technologie', 1, 'Comment s''appelle la technologie de paiement sans contact par téléphone ?', 'NFC', ARRAY['GPS', 'Bluetooth', 'LTE'], 'fr', true, 'Le NFC (Near Field Communication) permet les paiements sans contact à courte portée.'),
('technologie', 1, 'Quel est le nom de l''assistant vocal de Google ?', 'Google Assistant', ARRAY['Siri', 'Alexa', 'Cortana'], 'fr', true, 'Google Assistant est l''assistant vocal intelligent de Google, disponible sur smartphones et enceintes connectées.'),
('technologie', 1, 'Qu''est-ce qu''un selfie ?', 'Une photo de soi-même prise avec un smartphone', ARRAY['Un filtre photo', 'Une vidéo courte', 'Un type de réseau social'], 'fr', true, 'Le selfie est devenu un phénomène culturel avec l''amélioration des caméras frontales des smartphones.'),
('technologie', 1, 'Quelle entreprise a créé la console Wii ?', 'Nintendo', ARRAY['Sony', 'Microsoft', 'Sega'], 'fr', true, 'La Nintendo Wii est sortie en 2006 et a popularisé le jeu vidéo avec détection de mouvements.'),
('technologie', 1, 'Comment appelle-t-on un courrier électronique ?', 'Un email (ou courriel)', ARRAY['Un tweet', 'Un post', 'Un message texte'], 'fr', true, 'L''email est un moyen de communication électronique inventé dans les années 1970.'),
('technologie', 1, 'Quel service de Google permet de regarder des vidéos en ligne ?', 'YouTube', ARRAY['Google Drive', 'Google Maps', 'Google Photos'], 'fr', true, 'YouTube, fondé en 2005 et racheté par Google en 2006, est la plus grande plateforme vidéo au monde.'),
('technologie', 1, 'Qu''est-ce que le Bluetooth ?', 'Une technologie de communication sans fil à courte portée', ARRAY['Un type de câble', 'Un réseau social', 'Un antivirus'], 'fr', true, 'Le Bluetooth permet de connecter des appareils entre eux sans fil sur de courtes distances.'),
('technologie', 1, 'Quel type d''appareil est un iPad ?', 'Une tablette', ARRAY['Un smartphone', 'Un ordinateur portable', 'Une liseuse'], 'fr', true, 'L''iPad est une tablette tactile conçue par Apple, lancée en 2010.'),
('technologie', 1, 'Que signifie le sigle "LED" ?', 'Light Emitting Diode', ARRAY['Low Energy Device', 'Laser Emitting Display', 'Light Electronic Drive'], 'fr', true, 'Les LED sont des diodes électroluminescentes utilisées dans l''éclairage et les écrans.'),
('technologie', 1, 'Quel est le raccourci clavier pour annuler une action ?', 'Ctrl+Z', ARRAY['Ctrl+C', 'Ctrl+V', 'Ctrl+X'], 'fr', true, 'Ctrl+Z est le raccourci universel pour annuler la dernière action effectuée.'),
('technologie', 1, 'Comment s''appelle le stockage de données en ligne ?', 'Le cloud', ARRAY['Le cache', 'Le buffer', 'Le firewall'], 'fr', true, 'Le cloud computing permet de stocker et d''accéder à des données via Internet plutôt que localement.'),
('technologie', 1, 'Quelle plateforme est connue pour les vidéos courtes et les danses ?', 'TikTok', ARRAY['LinkedIn', 'Twitter', 'Pinterest'], 'fr', true, 'TikTok, développé par ByteDance, est devenu l''app la plus téléchargée au monde pour ses vidéos courtes.'),
('technologie', 1, 'Qu''est-ce qu''un hashtag ?', 'Un mot-clé précédé du signe # utilisé sur les réseaux sociaux', ARRAY['Un mot de passe', 'Un type de lien', 'Un virus informatique'], 'fr', true, 'Les hashtags permettent de catégoriser le contenu et de le rendre plus facilement trouvable.'),
('technologie', 1, 'Quel est le nom de la montre connectée de Samsung ?', 'Galaxy Watch', ARRAY['Apple Watch', 'Fitbit', 'Garmin'], 'fr', true, 'La Galaxy Watch est la montre connectée phare de Samsung, fonctionnant sous Wear OS.'),
('technologie', 1, 'Qu''est-ce qu''un podcast ?', 'Un contenu audio numérique disponible en streaming ou téléchargement', ARRAY['Un type de vidéo', 'Un réseau social', 'Un logiciel de musique'], 'fr', true, 'Le podcast est un format audio à la demande qui a connu un essor considérable depuis les années 2010.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('technologie', 2, 'Qui a cofondé Apple avec Steve Jobs ?', 'Steve Wozniak', ARRAY['Bill Gates', 'Tim Cook', 'Elon Musk'], 'fr', true, 'Steve Wozniak a cofondé Apple en 1976 avec Steve Jobs et Ronald Wayne.'),
('technologie', 2, 'En quelle année le premier iPhone a-t-il été lancé ?', '2007', ARRAY['2005', '2009', '2010'], 'fr', true, 'Le premier iPhone a été présenté par Steve Jobs le 9 janvier 2007.'),
('technologie', 2, 'Quel est le langage de programmation le plus utilisé sur le web ?', 'JavaScript', ARRAY['Python', 'Java', 'C++'], 'fr', true, 'JavaScript est le langage incontournable du développement web côté client.'),
('technologie', 2, 'Qui est considéré comme l''inventeur du World Wide Web ?', 'Tim Berners-Lee', ARRAY['Vint Cerf', 'Steve Jobs', 'Bill Gates'], 'fr', true, 'Tim Berners-Lee a inventé le WWW au CERN en 1989.'),
('technologie', 2, 'Quel est le nom de l''intelligence artificielle de Google ?', 'Gemini (anciennement Bard)', ARRAY['ChatGPT', 'Copilot', 'Claude'], 'fr', true, 'Google a lancé son IA conversationnelle Bard en 2023, renommée Gemini en 2024.'),
('technologie', 2, 'Quelle entreprise a développé le système d''exploitation Windows ?', 'Microsoft', ARRAY['Apple', 'Google', 'IBM'], 'fr', true, 'Microsoft a lancé Windows 1.0 en 1985 et domine le marché des PC depuis.'),
('technologie', 2, 'Qu''est-ce que la 5G ?', 'La cinquième génération de réseau mobile', ARRAY['Un nouveau Wi-Fi', 'Un satellite de communication', 'Un protocole Bluetooth'], 'fr', true, 'La 5G offre des débits plus rapides et une latence réduite par rapport à la 4G.'),
('technologie', 2, 'Quel est le nom du magasin d''applications Android ?', 'Google Play Store', ARRAY['App Store', 'Microsoft Store', 'Galaxy Store'], 'fr', true, 'Le Google Play Store est la plateforme officielle de distribution d''applications Android.'),
('technologie', 2, 'Qui a fondé Amazon ?', 'Jeff Bezos', ARRAY['Elon Musk', 'Mark Zuckerberg', 'Larry Page'], 'fr', true, 'Jeff Bezos a fondé Amazon en 1994 dans son garage à Seattle, initialement comme librairie en ligne.'),
('technologie', 2, 'Qu''est-ce qu''un VPN ?', 'Un réseau privé virtuel sécurisant la connexion Internet', ARRAY['Un virus de réseau', 'Un type de navigateur', 'Un protocole d''email'], 'fr', true, 'Un VPN chiffre le trafic Internet et masque l''adresse IP de l''utilisateur.'),
('technologie', 2, 'Quelle est la capacité de stockage standard d''un DVD ?', '4,7 Go', ARRAY['700 Mo', '25 Go', '1,44 Mo'], 'fr', true, 'Un DVD simple couche stocke 4,7 Go de données, bien plus qu''un CD (700 Mo).'),
('technologie', 2, 'Quel réseau social est orienté vers le monde professionnel ?', 'LinkedIn', ARRAY['Facebook', 'Instagram', 'TikTok'], 'fr', true, 'LinkedIn, fondé en 2003 et racheté par Microsoft en 2016, est le premier réseau social professionnel.'),
('technologie', 2, 'Qu''est-ce qu''un algorithme ?', 'Une suite d''instructions pour résoudre un problème', ARRAY['Un type de virus', 'Un langage de programmation', 'Un composant matériel'], 'fr', true, 'Les algorithmes sont la base de la programmation et du traitement des données.'),
('technologie', 2, 'Quel est le rôle d''un pare-feu (firewall) ?', 'Protéger un réseau contre les accès non autorisés', ARRAY['Accélérer Internet', 'Stocker des données', 'Refroidir l''ordinateur'], 'fr', true, 'Le pare-feu filtre le trafic réseau entrant et sortant selon des règles de sécurité.'),
('technologie', 2, 'Quel entreprise française est un leader mondial du jeu vidéo ?', 'Ubisoft', ARRAY['EA Sports', 'Activision', 'Bethesda'], 'fr', true, 'Ubisoft, fondée en 1986 en Bretagne, est connue pour Assassin''s Creed, Far Cry et Just Dance.'),
('technologie', 2, 'Qu''est-ce que l''intelligence artificielle ?', 'Un système informatique capable de simuler l''intelligence humaine', ARRAY['Un robot physique', 'Un super-ordinateur', 'Un réseau social avancé'], 'fr', true, 'L''IA englobe le machine learning, le deep learning et le traitement du langage naturel.'),
('technologie', 2, 'Quel est le format d''image utilisé pour les photos avec fond transparent ?', 'PNG', ARRAY['JPEG', 'BMP', 'TIFF'], 'fr', true, 'Le format PNG supporte la transparence, contrairement au JPEG.'),
('technologie', 2, 'Qui a créé le premier réseau social Myspace ?', 'Tom Anderson et Chris DeWolfe', ARRAY['Mark Zuckerberg', 'Jack Dorsey', 'Evan Spiegel'], 'fr', true, 'MySpace, lancé en 2003, a été le réseau social dominant avant l''arrivée de Facebook.'),
('technologie', 2, 'Qu''est-ce que le phishing ?', 'Une technique d''escroquerie en ligne imitant un site ou email légitime', ARRAY['Un type de virus', 'Un logiciel de pêche', 'Un protocole réseau'], 'fr', true, 'Le phishing (hameçonnage) vise à voler des données personnelles en se faisant passer pour une entité de confiance.'),
('technologie', 2, 'Quel composant détermine principalement la vitesse d''un ordinateur ?', 'Le processeur (CPU)', ARRAY['Le disque dur', 'L''écran', 'Le clavier'], 'fr', true, 'Le processeur exécute les instructions et sa vitesse se mesure en GHz.'),
('technologie', 2, 'Quelle entreprise a racheté WhatsApp en 2014 ?', 'Facebook (Meta)', ARRAY['Google', 'Microsoft', 'Apple'], 'fr', true, 'Facebook a racheté WhatsApp pour 19 milliards de dollars en 2014.'),
('technologie', 2, 'Qu''est-ce qu''un cookie sur Internet ?', 'Un petit fichier stocké par le navigateur pour mémoriser des informations', ARRAY['Un virus informatique', 'Un type de publicité', 'Un logiciel espion'], 'fr', true, 'Les cookies permettent aux sites web de se souvenir des préférences et de l''identité des utilisateurs.'),
('technologie', 2, 'Quel est le concurrent principal de l''App Store d''Apple ?', 'Google Play Store', ARRAY['Microsoft Store', 'Amazon Appstore', 'Samsung Galaxy Store'], 'fr', true, 'Le Google Play Store et l''App Store d''Apple sont les deux principales plateformes d''applications mobiles.'),
('technologie', 2, 'Qui a fondé SpaceX ?', 'Elon Musk', ARRAY['Jeff Bezos', 'Richard Branson', 'Bill Gates'], 'fr', true, 'SpaceX a été fondé en 2002 par Elon Musk avec l''objectif de coloniser Mars.'),
('technologie', 2, 'Qu''est-ce que la réalité augmentée (RA) ?', 'La superposition d''éléments virtuels sur le monde réel', ARRAY['Un monde entièrement virtuel', 'Un jeu vidéo en 3D', 'Un type d''hologramme'], 'fr', true, 'La réalité augmentée enrichit la vue du monde réel avec des informations numériques, comme dans Pokémon Go.'),
('technologie', 2, 'Quel est le nom du processeur conçu par Apple pour ses Mac ?', 'Apple Silicon (M1, M2, M3...)', ARRAY['Intel Core', 'AMD Ryzen', 'Snapdragon'], 'fr', true, 'Apple a lancé sa propre puce M1 en 2020, remplaçant les processeurs Intel dans ses Mac.'),
('technologie', 2, 'Qu''est-ce qu''un SSD ?', 'Un disque de stockage sans pièce mécanique, plus rapide qu''un disque dur', ARRAY['Un type de RAM', 'Un processeur graphique', 'Un format de fichier'], 'fr', true, 'Le SSD (Solid State Drive) utilise de la mémoire flash, sans disque rotatif.'),
('technologie', 2, 'Quelle technologie permet de recharger un téléphone sans câble ?', 'La charge sans fil (Qi)', ARRAY['Le Bluetooth', 'Le NFC', 'L''infrarouge'], 'fr', true, 'La norme Qi utilise l''induction électromagnétique pour transférer l''énergie sans contact.'),
('technologie', 2, 'Quel site web est connu comme l''encyclopédie en ligne collaborative ?', 'Wikipédia', ARRAY['Google', 'Quora', 'Reddit'], 'fr', true, 'Wikipédia, fondée en 2001, est une encyclopédie libre écrite par des bénévoles du monde entier.'),
('technologie', 2, 'Qu''est-ce qu''un deepfake ?', 'Une vidéo ou image falsifiée par intelligence artificielle', ARRAY['Un virus informatique avancé', 'Un type de cryptage', 'Un jeu vidéo'], 'fr', true, 'Les deepfakes utilisent le deep learning pour créer des contenus visuels très réalistes mais faux.'),
('technologie', 2, 'Quel est le nom du service de cartographie de Google ?', 'Google Maps', ARRAY['Apple Maps', 'Waze', 'OpenStreetMap'], 'fr', true, 'Google Maps, lancé en 2005, est le service de cartographie le plus utilisé au monde.'),
('technologie', 2, 'Qu''est-ce que le Dark Web ?', 'Une partie d''Internet non indexée et accessible via des logiciels spéciaux', ARRAY['Un site web en mode sombre', 'Un réseau social secret', 'Un type de virus'], 'fr', true, 'Le Dark Web nécessite un navigateur spécial comme Tor et héberge des activités légales et illégales.'),
('technologie', 2, 'Quelle entreprise a créé le premier système d''exploitation DOS ?', 'Microsoft', ARRAY['Apple', 'IBM', 'Intel'], 'fr', true, 'Microsoft a développé MS-DOS en 1981, qui est devenu le système d''exploitation standard des premiers PC IBM.'),
('technologie', 2, 'Qu''est-ce qu''une adresse IP ?', 'Un identifiant numérique attribué à chaque appareil connecté à Internet', ARRAY['Un mot de passe réseau', 'Un type de câble', 'Un protocole de messagerie'], 'fr', true, 'L''adresse IP (Internet Protocol) permet d''identifier et de localiser les appareils sur un réseau.'),
('technologie', 2, 'Quel est le langage de programmation créé par Guido van Rossum ?', 'Python', ARRAY['Java', 'Ruby', 'Swift'], 'fr', true, 'Python, créé en 1991, est devenu l''un des langages les plus populaires grâce à sa simplicité.'),
('technologie', 2, 'Quelle technologie est utilisée dans les casques de réalité virtuelle ?', 'Des écrans à haute résolution avec capteurs de mouvement', ARRAY['Des projecteurs holographiques', 'Des cristaux liquides transparents', 'Des lentilles à rayons X'], 'fr', true, 'Les casques VR utilisent des écrans OLED ou LCD avec suivi de mouvement pour créer une immersion 3D.'),
('technologie', 2, 'Qui a inventé le premier téléphone ?', 'Alexander Graham Bell', ARRAY['Thomas Edison', 'Nikola Tesla', 'Guglielmo Marconi'], 'fr', true, 'Alexander Graham Bell a breveté le téléphone en 1876.'),
('technologie', 2, 'Quel est le nom de l''IA conversationnelle d''OpenAI ?', 'ChatGPT', ARRAY['Siri', 'Alexa', 'Watson'], 'fr', true, 'ChatGPT, lancé en novembre 2022, est basé sur le modèle de langage GPT.'),
('technologie', 2, 'Qu''est-ce que le responsive design ?', 'La conception de sites web qui s''adaptent à toutes les tailles d''écran', ARRAY['Un type de langage de programmation', 'Un logiciel de design', 'Un format d''image'], 'fr', true, 'Le responsive design utilise des techniques CSS pour adapter l''affichage aux smartphones, tablettes et ordinateurs.'),
('technologie', 2, 'Quel est le rôle d''un antivirus ?', 'Détecter et supprimer les logiciels malveillants', ARRAY['Accélérer l''ordinateur', 'Bloquer la publicité', 'Sauvegarder les données'], 'fr', true, 'Les antivirus protègent les appareils contre les virus, malwares, ransomwares et autres menaces.'),
('technologie', 2, 'Quelle plateforme permet de partager du code source ?', 'GitHub', ARRAY['LinkedIn', 'Dropbox', 'Google Drive'], 'fr', true, 'GitHub, racheté par Microsoft en 2018, est la plus grande plateforme de développement collaboratif.'),
('technologie', 2, 'Qu''est-ce que le streaming ?', 'La diffusion de contenu en temps réel sans téléchargement', ARRAY['Le stockage de fichiers', 'La compression de données', 'Le partage de fichiers'], 'fr', true, 'Le streaming permet d''écouter de la musique ou regarder des vidéos sans les télécharger au préalable.'),
('technologie', 2, 'Quel réseau social est spécialisé dans le partage de photos et vidéos ?', 'Instagram', ARRAY['Twitter', 'LinkedIn', 'Reddit'], 'fr', true, 'Instagram, lancé en 2010 et racheté par Facebook en 2012, compte plus de 2 milliards d''utilisateurs.'),
('technologie', 2, 'Quelle entreprise a lancé les enceintes connectées Echo ?', 'Amazon', ARRAY['Google', 'Apple', 'Samsung'], 'fr', true, 'Amazon a lancé l''enceinte Echo avec l''assistant Alexa en 2014.'),
('technologie', 2, 'Qu''est-ce qu''un drone ?', 'Un aéronef sans pilote à bord, télécommandé ou autonome', ARRAY['Un robot terrestre', 'Un satellite miniature', 'Un type de caméra'], 'fr', true, 'Les drones sont utilisés pour la photographie aérienne, la livraison, l''agriculture et la surveillance.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('technologie', 3, 'Quel langage de programmation a été créé par Dennis Ritchie ?', 'C', ARRAY['Java', 'Python', 'BASIC'], 'fr', true, 'Dennis Ritchie a créé le langage C en 1972 aux laboratoires Bell, base de nombreux systèmes d''exploitation.'),
('technologie', 3, 'En quelle année a été envoyé le premier email ?', '1971', ARRAY['1969', '1975', '1980'], 'fr', true, 'Ray Tomlinson a envoyé le premier email en 1971 et a introduit le symbole @ dans les adresses.'),
('technologie', 3, 'Qu''est-ce que le machine learning ?', 'Un sous-domaine de l''IA où les machines apprennent à partir de données', ARRAY['Un type de processeur', 'Un langage de programmation', 'Un réseau informatique'], 'fr', true, 'Le machine learning permet aux algorithmes de s''améliorer automatiquement grâce à l''expérience.'),
('technologie', 3, 'Quel est le protocole principal utilisé pour le transfert de pages web ?', 'HTTP/HTTPS', ARRAY['FTP', 'SMTP', 'SSH'], 'fr', true, 'HTTP (HyperText Transfer Protocol) est le protocole standard pour le transfert de pages web.'),
('technologie', 3, 'Qui a créé le système d''exploitation Linux ?', 'Linus Torvalds', ARRAY['Bill Gates', 'Steve Jobs', 'Dennis Ritchie'], 'fr', true, 'Linus Torvalds a créé Linux en 1991 comme un noyau de système d''exploitation libre et open source.'),
('technologie', 3, 'Qu''est-ce que la blockchain ?', 'Une technologie de registre distribué et immuable', ARRAY['Un type de virus', 'Un réseau social', 'Un langage de programmation'], 'fr', true, 'La blockchain stocke des transactions de manière décentralisée et sécurisée, base des cryptomonnaies.'),
('technologie', 3, 'Quel est le rôle d''une API ?', 'Permettre à des logiciels de communiquer entre eux', ARRAY['Protéger contre les virus', 'Stocker des données', 'Afficher des pages web'], 'fr', true, 'Une API (Application Programming Interface) définit les méthodes de communication entre programmes.'),
('technologie', 3, 'En quelle année Google a-t-il été fondé ?', '1998', ARRAY['1996', '2000', '2002'], 'fr', true, 'Google a été fondé en 1998 par Larry Page et Sergey Brin à Stanford.'),
('technologie', 3, 'Qu''est-ce qu''un ransomware ?', 'Un malware qui chiffre les données et demande une rançon', ARRAY['Un antivirus', 'Un type de pare-feu', 'Un outil de sauvegarde'], 'fr', true, 'Les ransomwares (rançongiciels) bloquent l''accès aux fichiers jusqu''au paiement d''une rançon.'),
('technologie', 3, 'Quel est le principe du chiffrement de bout en bout ?', 'Seuls l''expéditeur et le destinataire peuvent lire les messages', ARRAY['Les messages sont stockés de façon sécurisée sur un serveur', 'Le message est compressé pour le transfert', 'Le serveur vérifie l''identité de chaque utilisateur'], 'fr', true, 'Le chiffrement de bout en bout empêche même le fournisseur du service de lire les messages.'),
('technologie', 3, 'Qui a inventé le transistor ?', 'John Bardeen, Walter Brattain et William Shockley', ARRAY['Alan Turing', 'John von Neumann', 'Claude Shannon'], 'fr', true, 'Le transistor a été inventé en 1947 aux laboratoires Bell, révolutionnant l''électronique.'),
('technologie', 3, 'Qu''est-ce que le protocole TCP/IP ?', 'Le protocole de communication fondamental d''Internet', ARRAY['Un type de câble réseau', 'Un navigateur web', 'Un format de fichier'], 'fr', true, 'TCP/IP est la suite de protocoles qui permet aux appareils de communiquer sur Internet.'),
('technologie', 3, 'Quel est le principe de la loi de Moore ?', 'Le nombre de transistors sur une puce double environ tous les deux ans', ARRAY['La vitesse d''Internet double chaque année', 'Le prix des ordinateurs baisse de moitié chaque an', 'La mémoire RAM double tous les six mois'], 'fr', true, 'Gordon Moore a formulé cette observation en 1965, qui s''est vérifiée pendant des décennies.'),
('technologie', 3, 'Qu''est-ce qu''un conteneur Docker ?', 'Un environnement isolé pour exécuter des applications', ARRAY['Un type de serveur physique', 'Un langage de programmation', 'Un format d''image'], 'fr', true, 'Docker permet de packager des applications avec leurs dépendances dans des conteneurs légers et portables.'),
('technologie', 3, 'Quelle est la différence entre le front-end et le back-end ?', 'Le front-end est la partie visible par l''utilisateur, le back-end est le côté serveur', ARRAY['Ce sont deux langages de programmation différents', 'Le front-end est plus rapide', 'Le back-end est toujours en Python'], 'fr', true, 'Le front-end concerne l''interface utilisateur (HTML, CSS, JS) et le back-end gère la logique serveur et les données.'),
('technologie', 3, 'Qu''est-ce que le cloud computing ?', 'L''utilisation de serveurs distants via Internet pour stocker et traiter des données', ARRAY['Un type de réseau local', 'Un logiciel de météo', 'Un nouveau type de processeur'], 'fr', true, 'Le cloud computing permet d''accéder à des ressources informatiques à la demande sans infrastructure locale.'),
('technologie', 3, 'Quel scientifique est considéré comme le père de l''informatique ?', 'Alan Turing', ARRAY['Charles Babbage', 'John von Neumann', 'Ada Lovelace'], 'fr', true, 'Alan Turing a posé les bases théoriques de l''informatique et de l''intelligence artificielle.'),
('technologie', 3, 'Qu''est-ce qu''une base de données relationnelle ?', 'Un système de stockage organisé en tables avec des relations entre elles', ARRAY['Un fichier Excel', 'Un disque dur partagé', 'Un type de cloud'], 'fr', true, 'Les bases de données relationnelles utilisent SQL et organisent les données en lignes et colonnes liées par des clés.'),
('technologie', 3, 'Quel est le langage principal utilisé pour styliser les pages web ?', 'CSS', ARRAY['HTML', 'JavaScript', 'PHP'], 'fr', true, 'CSS (Cascading Style Sheets) contrôle la mise en forme visuelle des pages web.'),
('technologie', 3, 'Qu''est-ce que l''Internet des objets (IoT) ?', 'L''interconnexion d''objets physiques à Internet', ARRAY['Un nouveau type d''Internet', 'Un réseau social pour les machines', 'Un protocole de sécurité'], 'fr', true, 'L''IoT connecte des appareils du quotidien (thermostats, montres, frigos) à Internet pour échanger des données.'),
('technologie', 3, 'Qui est Ada Lovelace ?', 'La première programmeuse de l''histoire', ARRAY['L''inventrice d''Internet', 'La créatrice de Python', 'La fondatrice d''Apple'], 'fr', true, 'Ada Lovelace a écrit le premier algorithme destiné à être exécuté par la machine analytique de Babbage en 1843.'),
('technologie', 3, 'Qu''est-ce que l''authentification à deux facteurs (2FA) ?', 'Une méthode de sécurité nécessitant deux preuves d''identité différentes', ARRAY['Un double mot de passe', 'Deux comptes utilisateur', 'Un antivirus avancé'], 'fr', true, 'La 2FA combine généralement un mot de passe et un code envoyé par SMS ou généré par une app.'),
('technologie', 3, 'Quel est le principe d''un réseau neuronal artificiel ?', 'Un modèle inspiré du cerveau humain avec des couches de neurones interconnectés', ARRAY['Un réseau informatique très rapide', 'Un type de câblage', 'Un système d''exploitation'], 'fr', true, 'Les réseaux neuronaux artificiels sont la base du deep learning et de nombreuses applications d''IA.'),
('technologie', 3, 'Qu''est-ce que le Big Data ?', 'Des ensembles de données trop volumineux pour les outils traditionnels', ARRAY['Un gros disque dur', 'Un type de serveur', 'Un réseau social'], 'fr', true, 'Le Big Data se caractérise par les 3V : Volume, Vélocité et Variété des données.'),
('technologie', 3, 'Quelle est la différence entre HTTP et HTTPS ?', 'HTTPS chiffre les données échangées grâce au protocole SSL/TLS', ARRAY['HTTPS est plus lent', 'HTTP est plus sécurisé', 'Il n''y a aucune différence'], 'fr', true, 'Le S de HTTPS signifie Secure et garantit que les données sont chiffrées entre le navigateur et le serveur.'),
('technologie', 3, 'Quel type de mémoire conserve les données même sans alimentation ?', 'La mémoire non volatile (ROM, SSD, Flash)', ARRAY['La RAM', 'Le cache L1', 'La mémoire vive'], 'fr', true, 'La mémoire non volatile (ROM, SSD, clé USB) conserve les données même hors tension, contrairement à la RAM.'),
('technologie', 3, 'Qu''est-ce que le Open Source ?', 'Un logiciel dont le code source est accessible et modifiable par tous', ARRAY['Un logiciel gratuit uniquement', 'Un type de licence payante', 'Un format de fichier ouvert'], 'fr', true, 'Le mouvement open source encourage la collaboration et la transparence dans le développement logiciel.'),
('technologie', 3, 'Quel est le rôle d''un CDN (Content Delivery Network) ?', 'Distribuer le contenu web depuis des serveurs proches de l''utilisateur', ARRAY['Compresser les fichiers', 'Créer des sites web', 'Protéger contre les hackers'], 'fr', true, 'Les CDN réduisent la latence en servant le contenu depuis des serveurs géographiquement proches des utilisateurs.'),
('technologie', 3, 'Qu''est-ce que la réalité virtuelle (VR) ?', 'Un environnement entièrement simulé par ordinateur dans lequel l''utilisateur est immergé', ARRAY['Un filtre photo avancé', 'Un jeu vidéo en 3D', 'Un hologramme'], 'fr', true, 'La réalité virtuelle utilise un casque pour plonger l''utilisateur dans un monde numérique interactif.'),
('technologie', 3, 'Quel est le nom du premier ordinateur électronique programmable ?', 'ENIAC', ARRAY['UNIVAC', 'IBM 701', 'Colossus'], 'fr', true, 'L''ENIAC (Electronic Numerical Integrator and Computer) a été achevé en 1945 à l''université de Pennsylvanie.'),
('technologie', 3, 'Qu''est-ce que le DevOps ?', 'Une approche combinant développement logiciel et opérations informatiques', ARRAY['Un langage de programmation', 'Un type de serveur', 'Un système d''exploitation'], 'fr', true, 'Le DevOps vise à raccourcir le cycle de développement et à fournir des logiciels de meilleure qualité.'),
('technologie', 3, 'Quelle est la différence entre IA faible et IA forte ?', 'L''IA faible est spécialisée, l''IA forte aurait une intelligence générale comparable à l''humain', ARRAY['L''IA forte est plus rapide', 'L''IA faible est plus ancienne', 'Ce sont des synonymes'], 'fr', true, 'L''IA actuelle est faible (spécialisée). L''IA forte (AGI) reste un objectif théorique non atteint.'),
('technologie', 3, 'Qu''est-ce qu''un microcontrôleur ?', 'Un petit ordinateur sur une seule puce électronique', ARRAY['Un processeur de PC', 'Un composant audio', 'Un type de capteur'], 'fr', true, 'Les microcontrôleurs (comme Arduino) contiennent processeur, mémoire et entrées/sorties sur une seule puce.'),
('technologie', 3, 'Quel protocole est utilisé pour envoyer des emails ?', 'SMTP', ARRAY['HTTP', 'FTP', 'SSH'], 'fr', true, 'SMTP (Simple Mail Transfer Protocol) est le protocole standard pour l''envoi d''emails.'),
('technologie', 3, 'Qu''est-ce que la latence en informatique ?', 'Le délai entre l''envoi d''une requête et la réception de la réponse', ARRAY['La vitesse de téléchargement', 'La capacité de stockage', 'La résolution d''un écran'], 'fr', true, 'Une faible latence est cruciale pour les jeux en ligne et les applications en temps réel.'),
('technologie', 3, 'Quelle technologie est à la base du Bitcoin ?', 'La blockchain', ARRAY['L''intelligence artificielle', 'Le cloud computing', 'Le machine learning'], 'fr', true, 'Le Bitcoin, créé en 2009 par Satoshi Nakamoto, utilise la blockchain pour sécuriser les transactions.'),
('technologie', 3, 'Qu''est-ce qu''un pixel ?', 'Le plus petit élément d''une image numérique', ARRAY['Un type de câble', 'Un composant de processeur', 'Un format de fichier'], 'fr', true, 'Le mot pixel vient de "picture element". La résolution d''un écran se mesure en nombre de pixels.'),
('technologie', 3, 'Quel est le principe du RAID en stockage ?', 'Combiner plusieurs disques pour la performance ou la redondance', ARRAY['Compresser les données', 'Chiffrer les fichiers', 'Accélérer Internet'], 'fr', true, 'Le RAID (Redundant Array of Independent Disks) offre différents niveaux de performance et de sécurité des données.'),
('technologie', 3, 'Qu''est-ce que le Agile en développement logiciel ?', 'Une méthodologie itérative et collaborative de gestion de projet', ARRAY['Un langage de programmation', 'Un type de test', 'Un framework front-end'], 'fr', true, 'La méthode Agile privilégie la flexibilité, les itérations courtes et la collaboration étroite avec le client.'),
('technologie', 3, 'Quelle entreprise a développé le processeur x86 ?', 'Intel', ARRAY['AMD', 'ARM', 'IBM'], 'fr', true, 'Intel a créé l''architecture x86 en 1978 avec le processeur 8086, devenue la norme pour les PC.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('technologie', 4, 'Qu''est-ce que le principe de Turing-complet ?', 'Un système capable de simuler n''importe quelle machine de Turing', ARRAY['Un ordinateur qui passe le test de Turing', 'Un programme sans bugs', 'Un système d''exploitation universel'], 'fr', true, 'Un langage Turing-complet peut théoriquement résoudre tout problème calculable.'),
('technologie', 4, 'Qu''est-ce que le protocole WebSocket ?', 'Un protocole de communication bidirectionnelle en temps réel entre client et serveur', ARRAY['Un protocole de transfert de fichiers', 'Un type de navigateur web', 'Un format de données JSON'], 'fr', true, 'WebSocket maintient une connexion persistante permettant au serveur d''envoyer des données au client sans requête.'),
('technologie', 4, 'Qu''est-ce que la complexité algorithmique O(n log n) ?', 'Un temps d''exécution qui croît légèrement plus vite que linéairement', ARRAY['Un temps constant', 'Un temps exponentiel', 'Un temps quadratique'], 'fr', true, 'O(n log n) est typique des algorithmes de tri efficaces comme le tri fusion (mergesort).'),
('technologie', 4, 'Qu''est-ce que FPGA ?', 'Un circuit intégré programmable après fabrication', ARRAY['Un langage de programmation', 'Un protocole réseau', 'Un type de mémoire RAM'], 'fr', true, 'Un FPGA (Field-Programmable Gate Array) peut être reconfiguré pour des tâches spécifiques après fabrication.'),
('technologie', 4, 'Qu''est-ce que le théorème CAP en systèmes distribués ?', 'Un système distribué ne peut garantir simultanément Consistance, Disponibilité et Tolérance au partitionnement', ARRAY['Un protocole de sécurité', 'Un algorithme de tri', 'Un type de base de données'], 'fr', true, 'Le théorème CAP (Brewer) impose un compromis entre ces trois propriétés dans les systèmes distribués.'),
('technologie', 4, 'Qu''est-ce que Kubernetes ?', 'Un système d''orchestration de conteneurs', ARRAY['Un langage de programmation', 'Un navigateur web', 'Un système d''exploitation'], 'fr', true, 'Kubernetes (K8s), créé par Google, automatise le déploiement et la gestion de conteneurs à grande échelle.'),
('technologie', 4, 'Qu''est-ce qu''une attaque par injection SQL ?', 'L''insertion de code SQL malveillant dans les entrées d''une application', ARRAY['Un virus qui corrompt les bases de données', 'Un type de DDoS', 'Le vol de mots de passe'], 'fr', true, 'L''injection SQL exploite les failles de validation des entrées pour manipuler les bases de données.'),
('technologie', 4, 'Qu''est-ce que le paradigme de programmation fonctionnelle ?', 'Un style de programmation basé sur les fonctions pures et l''immutabilité', ARRAY['La programmation avec des classes et objets', 'La programmation séquentielle', 'La programmation par événements'], 'fr', true, 'La programmation fonctionnelle évite les effets de bord et utilise des fonctions comme valeurs de premier ordre.'),
('technologie', 4, 'Qu''est-ce que l''architecture ARM ?', 'Une architecture de processeur à jeu d''instructions réduit (RISC)', ARRAY['Un type de serveur', 'Un langage assembleur', 'Un protocole de communication'], 'fr', true, 'ARM domine le marché mobile grâce à sa faible consommation énergétique. Apple Silicon est basé sur ARM.'),
('technologie', 4, 'Qu''est-ce qu''un GAN (Generative Adversarial Network) ?', 'Un modèle d''IA où deux réseaux neuronaux s''entraînent mutuellement en compétition', ARRAY['Un type de réseau informatique', 'Un protocole de sécurité', 'Un algorithme de compression'], 'fr', true, 'Les GANs, inventés par Ian Goodfellow en 2014, peuvent générer des images, des vidéos et du texte réalistes.'),
('technologie', 4, 'Qu''est-ce que le Zero Trust en cybersécurité ?', 'Un modèle de sécurité ne faisant confiance à aucun utilisateur ou appareil par défaut', ARRAY['Un pare-feu avancé', 'Un type de cryptage', 'Un protocole VPN'], 'fr', true, 'Le Zero Trust vérifie chaque accès indépendamment, même pour les utilisateurs internes au réseau.'),
('technologie', 4, 'Qu''est-ce que le protocole QUIC ?', 'Un protocole de transport basé sur UDP développé par Google pour accélérer le web', ARRAY['Un langage de programmation', 'Un format d''image', 'Un type de base de données'], 'fr', true, 'QUIC est utilisé dans HTTP/3 et offre des connexions plus rapides et plus fiables que TCP.'),
('technologie', 4, 'Qu''est-ce qu''un compilateur JIT (Just-In-Time) ?', 'Un compilateur qui traduit le code en langage machine pendant l''exécution', ARRAY['Un compilateur qui corrige les erreurs automatiquement', 'Un outil de débogage', 'Un type de mémoire cache'], 'fr', true, 'La compilation JIT combine les avantages de l''interprétation et de la compilation, utilisée par Java et JavaScript.'),
('technologie', 4, 'Qu''est-ce que le sharding dans les bases de données ?', 'La répartition horizontale des données sur plusieurs serveurs', ARRAY['La compression des données', 'Le chiffrement des tables', 'La duplication des données'], 'fr', true, 'Le sharding distribue les données sur plusieurs machines pour améliorer les performances et la scalabilité.'),
('technologie', 4, 'Qu''est-ce que WebAssembly (WASM) ?', 'Un format binaire permettant d''exécuter du code haute performance dans le navigateur', ARRAY['Un framework JavaScript', 'Un langage de balisage', 'Un protocole web'], 'fr', true, 'WebAssembly permet d''exécuter du C/C++/Rust dans le navigateur à des vitesses proches du natif.'),
('technologie', 4, 'Qu''est-ce que l''architecture microservices ?', 'Un style d''architecture où l''application est décomposée en services indépendants', ARRAY['Un serveur très petit', 'Un microprocesseur', 'Un type de base de données'], 'fr', true, 'Les microservices permettent un développement, déploiement et mise à l''échelle indépendants de chaque service.'),
('technologie', 4, 'Qu''est-ce que le gradient descent en machine learning ?', 'Un algorithme d''optimisation qui minimise une fonction de coût de manière itérative', ARRAY['Un type de réseau neuronal', 'Un algorithme de tri', 'Une technique de compression'], 'fr', true, 'Le gradient descent ajuste les paramètres d''un modèle en suivant la pente de la fonction de coût.'),
('technologie', 4, 'Qu''est-ce que le protocole SSH ?', 'Un protocole de communication sécurisé pour accéder à distance à des machines', ARRAY['Un protocole de transfert de fichiers', 'Un type de VPN', 'Un format de clé de chiffrement'], 'fr', true, 'SSH (Secure Shell) chiffre toutes les communications et remplace les protocoles non sécurisés comme Telnet.'),
('technologie', 4, 'Qu''est-ce qu''une table de hachage ?', 'Une structure de données associant des clés à des valeurs via une fonction de hachage', ARRAY['Une table de base de données', 'Un type de chiffrement', 'Un algorithme de tri'], 'fr', true, 'Les tables de hachage offrent un accès en O(1) en moyenne, utilisées dans les dictionnaires et les caches.'),
('technologie', 4, 'Qu''est-ce que la virtualisation ?', 'La création de versions virtuelles de ressources informatiques (serveurs, stockage, réseaux)', ARRAY['La réalité virtuelle', 'Un type de cloud', 'La simulation 3D'], 'fr', true, 'La virtualisation permet d''exécuter plusieurs systèmes d''exploitation sur une seule machine physique.'),
('technologie', 4, 'Qu''est-ce que GraphQL ?', 'Un langage de requête pour les API permettant de demander exactement les données nécessaires', ARRAY['Un type de base de données graphe', 'Un outil de visualisation', 'Un langage de programmation'], 'fr', true, 'GraphQL, créé par Facebook en 2012, offre une alternative flexible aux API REST.'),
('technologie', 4, 'Qu''est-ce que le edge computing ?', 'Le traitement des données au plus près de leur source plutôt que dans un cloud centralisé', ARRAY['Un type de réseau', 'Un navigateur web', 'Un système d''exploitation'], 'fr', true, 'L''edge computing réduit la latence en traitant les données localement, utile pour l''IoT et les véhicules autonomes.'),
('technologie', 4, 'Qu''est-ce qu''une race condition en programmation ?', 'Un bug survenant quand le résultat dépend de l''ordre d''exécution de processus concurrents', ARRAY['Un type de boucle infinie', 'Une erreur de syntaxe', 'Un problème de mémoire'], 'fr', true, 'Les race conditions sont difficiles à détecter et reproduire car elles dépendent du timing des threads.'),
('technologie', 4, 'Qu''est-ce que le chiffrement asymétrique ?', 'Un chiffrement utilisant une paire de clés : une publique et une privée', ARRAY['Un chiffrement avec une seule clé', 'Un chiffrement sans clé', 'Un type de compression'], 'fr', true, 'Le chiffrement asymétrique (RSA, ECC) est utilisé pour les signatures numériques et les connexions HTTPS.'),
('technologie', 4, 'Qu''est-ce qu''un Transformer en IA ?', 'Une architecture de réseau neuronal basée sur le mécanisme d''attention', ARRAY['Un robot physique', 'Un algorithme de tri', 'Un type de processeur'], 'fr', true, 'L''architecture Transformer, introduite en 2017 par Google, est la base de GPT, BERT et la plupart des LLMs modernes.'),
('technologie', 4, 'Qu''est-ce que le concept de garbage collection ?', 'Un mécanisme automatique de libération de la mémoire inutilisée', ARRAY['La suppression de fichiers temporaires', 'Le nettoyage de virus', 'La défragmentation du disque'], 'fr', true, 'Le garbage collector libère automatiquement la mémoire des objets qui ne sont plus référencés.'),
('technologie', 4, 'Qu''est-ce que le protocole BGP ?', 'Le protocole de routage principal d''Internet entre systèmes autonomes', ARRAY['Un protocole de messagerie', 'Un format de fichier', 'Un type de VPN'], 'fr', true, 'BGP (Border Gateway Protocol) est essentiel au fonctionnement d''Internet, gérant le routage entre réseaux.'),
('technologie', 4, 'Qu''est-ce que le test de Turing ?', 'Un test évaluant si une machine peut imiter l''intelligence humaine de façon indiscernable', ARRAY['Un test de vitesse de calcul', 'Un test de sécurité', 'Un test de compatibilité logicielle'], 'fr', true, 'Proposé par Alan Turing en 1950, il évalue si un humain peut distinguer les réponses d''une machine de celles d''un humain.'),
('technologie', 4, 'Qu''est-ce que le principe SOLID en programmation ?', 'Cinq principes de conception orientée objet pour un code maintenable', ARRAY['Un langage de programmation', 'Un type de test', 'Un framework'], 'fr', true, 'SOLID : Single responsibility, Open-closed, Liskov substitution, Interface segregation, Dependency inversion.'),
('technologie', 4, 'Qu''est-ce que le DNS (Domain Name System) ?', 'Le système traduisant les noms de domaine en adresses IP', ARRAY['Un protocole de sécurité', 'Un type de serveur web', 'Un format d''adresse email'], 'fr', true, 'Le DNS est souvent comparé à un annuaire téléphonique d''Internet, convertissant google.com en adresse IP.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('technologie', 5, 'En quelle année le protocole TCP/IP a-t-il été standardisé ?', '1983', ARRAY['1969', '1975', '1990'], 'fr', true, 'Le 1er janvier 1983, ARPANET a adopté TCP/IP, date considérée comme la naissance d''Internet.'),
('technologie', 5, 'Qu''est-ce que le problème P vs NP ?', 'La question de savoir si tout problème dont la solution est vérifiable en temps polynomial est aussi résoluble en temps polynomial', ARRAY['Un bug informatique célèbre', 'Un problème de mémoire', 'Un paradoxe de l''IA'], 'fr', true, 'P vs NP est l''un des problèmes du millénaire non résolus, avec un prix d''un million de dollars.'),
('technologie', 5, 'Qu''est-ce que le calcul quantique utilise comme unité fondamentale ?', 'Le qubit', ARRAY['Le bit', 'Le byte', 'Le quantum'], 'fr', true, 'Contrairement au bit classique (0 ou 1), le qubit peut être dans une superposition des deux états simultanément.'),
('technologie', 5, 'Qu''est-ce que l''algorithme de Shor ?', 'Un algorithme quantique capable de factoriser de grands nombres en temps polynomial', ARRAY['Un algorithme de tri quantique', 'Un protocole de chiffrement quantique', 'Un algorithme de recherche'], 'fr', true, 'L''algorithme de Shor menace la cryptographie RSA car il pourrait casser le chiffrement sur un ordinateur quantique.'),
('technologie', 5, 'Qu''est-ce que la mémoire associative (CAM) ?', 'Une mémoire qui recherche par contenu plutôt que par adresse', ARRAY['Un type de RAM', 'Un cache de processeur', 'Une mémoire de stockage de masse'], 'fr', true, 'La CAM (Content-Addressable Memory) est utilisée dans les routeurs réseau pour des recherches ultra-rapides.'),
('technologie', 5, 'Qu''est-ce que le consensus Paxos ?', 'Un algorithme de consensus pour les systèmes distribués tolérants aux pannes', ARRAY['Un protocole de blockchain', 'Un langage de programmation', 'Un type de base de données'], 'fr', true, 'Paxos, proposé par Leslie Lamport, garantit l''accord entre nœuds même en cas de défaillance partielle.'),
('technologie', 5, 'Qu''est-ce que la correction d''erreur quantique ?', 'Des techniques pour protéger l''information quantique contre la décohérence et les erreurs', ARRAY['La correction automatique de bugs', 'Le débogage de programmes quantiques', 'La vérification de calculs classiques'], 'fr', true, 'La correction d''erreur quantique est essentielle pour construire des ordinateurs quantiques fiables à grande échelle.'),
('technologie', 5, 'Qu''est-ce que l''architecture Von Neumann ?', 'Une architecture où programme et données partagent la même mémoire et le même bus', ARRAY['Une architecture avec mémoires séparées pour code et données', 'Un type de processeur parallèle', 'Un modèle de réseau neuronal'], 'fr', true, 'L''architecture Von Neumann, proposée en 1945, est la base de la plupart des ordinateurs modernes.'),
('technologie', 5, 'Qu''est-ce que le lambda calcul ?', 'Un système formel de logique mathématique pour exprimer le calcul', ARRAY['Un type de fonction Python', 'Un calcul de performance', 'Un algorithme de tri'], 'fr', true, 'Le lambda calcul, créé par Alonzo Church, est équivalent en puissance à la machine de Turing et fonde la programmation fonctionnelle.'),
('technologie', 5, 'Qu''est-ce que la mémoire transactionnelle ?', 'Un mécanisme de concurrence permettant de regrouper des opérations mémoire en transactions atomiques', ARRAY['Un type de stockage persistant', 'Une mémoire pour les transactions bancaires', 'Un cache de base de données'], 'fr', true, 'La mémoire transactionnelle simplifie la programmation concurrente en évitant les verrous explicites.'),
('technologie', 5, 'Qu''est-ce que le théorème de Rice ?', 'Toute propriété non triviale des langages reconnus par les machines de Turing est indécidable', ARRAY['Un théorème sur la complexité du tri', 'Un principe de cryptographie', 'Une loi de l''informatique quantique'], 'fr', true, 'Le théorème de Rice étend le problème de l''arrêt et limite fondamentalement l''analyse statique de programmes.'),
('technologie', 5, 'Qu''est-ce que l''homomorphic encryption ?', 'Un chiffrement permettant d''effectuer des calculs sur des données chiffrées sans les déchiffrer', ARRAY['Un chiffrement symétrique avancé', 'Un protocole de VPN', 'Un type de signature numérique'], 'fr', true, 'Le chiffrement homomorphe permettrait le traitement de données dans le cloud sans exposer les données en clair.'),
('technologie', 5, 'Qu''est-ce que l''algorithme de Grover ?', 'Un algorithme quantique pour la recherche dans une base non triée en O(√n)', ARRAY['Un algorithme de tri quantique', 'Un algorithme de chiffrement', 'Un algorithme de compression'], 'fr', true, 'L''algorithme de Grover offre une accélération quadratique par rapport à la recherche classique en O(n).'),
('technologie', 5, 'Qu''est-ce que la preuve à divulgation nulle de connaissance (Zero-Knowledge Proof) ?', 'Une preuve permettant de prouver la connaissance d''un secret sans le révéler', ARRAY['Un test de sécurité', 'Un type de mot de passe', 'Un protocole d''authentification biométrique'], 'fr', true, 'Les ZK proofs sont utilisées en blockchain et cryptographie pour la vérification sans divulgation.'),
('technologie', 5, 'Qu''est-ce que le problème de l''arrêt (Halting Problem) ?', 'L''impossibilité de déterminer algorithmiquement si un programme s''arrêtera ou bouclera indéfiniment', ARRAY['Le plantage d''un ordinateur', 'Un bug dans un programme', 'Le redémarrage forcé d''un système'], 'fr', true, 'Alan Turing a prouvé en 1936 que le problème de l''arrêt est indécidable, posant une limite fondamentale de l''informatique.'),
('technologie', 5, 'Qu''est-ce que la distribution quantique de clés (QKD) ?', 'Un protocole de distribution de clés de chiffrement basé sur la mécanique quantique', ARRAY['Un protocole de partage de fichiers', 'Un algorithme de compression quantique', 'Un type de réseau quantique'], 'fr', true, 'La QKD (comme le protocole BB84) garantit théoriquement une sécurité inconditionnelle basée sur les lois de la physique.'),
('technologie', 5, 'Qu''est-ce qu''un ASIC ?', 'Un circuit intégré conçu pour une application spécifique', ARRAY['Un processeur généraliste', 'Un type de mémoire', 'Un protocole de communication'], 'fr', true, 'Les ASICs (Application-Specific Integrated Circuits) sont optimisés pour une tâche précise, comme le minage de Bitcoin.'),
('technologie', 5, 'Qu''est-ce que le modèle OSI ?', 'Un modèle en 7 couches décrivant les communications réseau', ARRAY['Un système d''exploitation', 'Un langage de programmation', 'Un protocole de sécurité'], 'fr', true, 'Le modèle OSI (Open Systems Interconnection) structure les communications réseau de la couche physique à l''application.'),
('technologie', 5, 'Qu''est-ce que le consensus Byzantine Fault Tolerance ?', 'Un mécanisme permettant à un système distribué de fonctionner malgré des nœuds malveillants', ARRAY['Un protocole de chiffrement', 'Un algorithme de tri distribué', 'Un type de base de données'], 'fr', true, 'Le BFT résout le problème des généraux byzantins, fondamental pour les blockchains et systèmes distribués sécurisés.'),
('technologie', 5, 'Qu''est-ce que le Persistent Memory (PMEM) ?', 'Une mémoire combinant la vitesse de la RAM avec la persistance du stockage', ARRAY['Un type de SSD', 'Un cache L3 agrandi', 'Un disque dur haute performance'], 'fr', true, 'Intel Optane est un exemple de PMEM, offrant des performances proches de la DRAM avec conservation des données hors tension.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('technologie', 1, 'What does Wi-Fi stand for?', 'Wireless Fidelity', ARRAY['Wired Fidelity', 'Wide Frequency', 'Web Interface'], 'en', true, 'Wi-Fi is a trademark for wireless networking technology that connects devices to the internet.'),
('technologie', 1, 'Which company created the iPhone?', 'Apple', ARRAY['Samsung', 'Google', 'Microsoft'], 'en', true, 'Apple launched the first iPhone in 2007, revolutionizing the smartphone industry.'),
('technologie', 1, 'What is the most popular search engine in the world?', 'Google', ARRAY['Bing', 'Yahoo', 'DuckDuckGo'], 'en', true, 'Google handles over 90% of global search queries.'),
('technologie', 1, 'What does GPS stand for?', 'Global Positioning System', ARRAY['General Position Service', 'Geographic Placement System', 'Global Protocol Standard'], 'en', true, 'GPS uses a network of satellites to determine precise geographic location.'),
('technologie', 1, 'Which company makes the PlayStation?', 'Sony', ARRAY['Microsoft', 'Nintendo', 'Sega'], 'en', true, 'Sony launched the original PlayStation in 1994 and continues the series today.'),
('technologie', 1, 'What is Android?', 'A mobile operating system by Google', ARRAY['A programming language', 'A type of robot', 'A web browser'], 'en', true, 'Android is the world''s most popular mobile OS, powering billions of devices.'),
('technologie', 1, 'What does the ''www'' in a web address stand for?', 'World Wide Web', ARRAY['Wide World Web', 'Web Wide World', 'World Web Wide'], 'en', true, 'The World Wide Web was invented by Tim Berners-Lee at CERN in 1989.'),
('technologie', 1, 'What is a selfie?', 'A photo of yourself taken with a smartphone', ARRAY['A photo filter', 'A short video', 'A social media app'], 'en', true, 'The selfie became a cultural phenomenon with the improvement of front-facing cameras.'),
('technologie', 1, 'Which social media platform is known for short videos?', 'TikTok', ARRAY['LinkedIn', 'Twitter', 'Pinterest'], 'en', true, 'TikTok, developed by ByteDance, became the world''s most downloaded app for its short-form videos.'),
('technologie', 1, 'What is an emoji?', 'A small pictogram used in digital messages', ARRAY['A computer virus', 'A file type', 'A programming language'], 'en', true, 'Emojis originated in Japan in the late 1990s and became a Unicode standard.'),
('technologie', 1, 'What keyboard shortcut copies text?', 'Ctrl+C (or Cmd+C on Mac)', ARRAY['Ctrl+V', 'Ctrl+X', 'Ctrl+Z'], 'en', true, 'Ctrl+C copies the selected item to the clipboard.'),
('technologie', 1, 'Which company created Windows?', 'Microsoft', ARRAY['Apple', 'Google', 'IBM'], 'en', true, 'Microsoft released Windows 1.0 in 1985 and has dominated the PC market since.'),
('technologie', 1, 'What does USB stand for?', 'Universal Serial Bus', ARRAY['Ultra Speed Buffer', 'United System Board', 'Unified Storage Base'], 'en', true, 'USB is a standard for connecting devices for data transfer and power.'),
('technologie', 1, 'What is Bluetooth?', 'A wireless communication technology for short distances', ARRAY['A type of cable', 'A social network', 'An antivirus'], 'en', true, 'Bluetooth connects devices wirelessly over short distances, named after a Viking king.'),
('technologie', 1, 'What type of device is an iPad?', 'A tablet', ARRAY['A smartphone', 'A laptop', 'An e-reader'], 'en', true, 'The iPad is a tablet designed by Apple, first launched in 2010.'),
('technologie', 1, 'What is the name of Amazon''s voice assistant?', 'Alexa', ARRAY['Siri', 'Cortana', 'Google Assistant'], 'en', true, 'Alexa powers Amazon''s Echo speakers and other smart devices.'),
('technologie', 1, 'What is a QR code used for?', 'Accessing content by scanning it with a smartphone', ARRAY['Protecting files', 'Sending emails', 'Creating passwords'], 'en', true, 'QR codes (Quick Response) can encode URLs, text, or contact information.'),
('technologie', 1, 'What does LED stand for?', 'Light Emitting Diode', ARRAY['Low Energy Device', 'Laser Emitting Display', 'Light Electronic Drive'], 'en', true, 'LEDs are semiconductor devices used in lighting, displays, and indicators.'),
('technologie', 1, 'Which messaging app has a green icon with a white phone?', 'WhatsApp', ARRAY['Telegram', 'Signal', 'Viber'], 'en', true, 'WhatsApp, bought by Facebook (Meta) in 2014, is the most used messaging app worldwide.'),
('technologie', 1, 'What is cloud storage?', 'Storing data online on remote servers', ARRAY['Storing data on USB drives', 'A weather tracking app', 'A type of hard drive'], 'en', true, 'Cloud storage lets you access files from anywhere via the internet.'),
('technologie', 1, 'What keyboard shortcut undoes an action?', 'Ctrl+Z', ARRAY['Ctrl+C', 'Ctrl+V', 'Ctrl+X'], 'en', true, 'Ctrl+Z is the universal shortcut to undo the last action.'),
('technologie', 1, 'Which device distributes internet in a home?', 'A router', ARRAY['A modem only', 'A switch', 'A server'], 'en', true, 'Routers distribute internet connections to multiple devices in a network.'),
('technologie', 1, 'What does NFC stand for?', 'Near Field Communication', ARRAY['New File Connection', 'Network Frequency Control', 'Normal Function Code'], 'en', true, 'NFC enables contactless payments and data exchange over very short distances.'),
('technologie', 1, 'What is a hashtag?', 'A keyword preceded by # used on social media', ARRAY['A password', 'A type of link', 'A computer virus'], 'en', true, 'Hashtags help categorize content and make it more discoverable on social platforms.'),
('technologie', 1, 'What company created Facebook?', 'Meta (Mark Zuckerberg)', ARRAY['Google', 'Apple', 'Amazon'], 'en', true, 'Facebook was created by Mark Zuckerberg in 2004 at Harvard. The company renamed to Meta in 2021.'),
('technologie', 1, 'What is Netflix?', 'A video streaming service', ARRAY['A social media platform', 'A search engine', 'An email provider'], 'en', true, 'Netflix started as a DVD rental service in 1997 and became the leading streaming platform.'),
('technologie', 1, 'Which browser is made by Mozilla?', 'Firefox', ARRAY['Chrome', 'Safari', 'Edge'], 'en', true, 'Mozilla Firefox is an open-source web browser launched in 2004.'),
('technologie', 1, 'What is the @ symbol in email addresses called?', 'At sign (at symbol)', ARRAY['Hashtag', 'Ampersand', 'Asterisk'], 'en', true, 'The @ symbol separates the username from the domain name in an email address.'),
('technologie', 1, 'What is a podcast?', 'An audio program available for streaming or download', ARRAY['A type of video', 'A social network', 'A music software'], 'en', true, 'Podcasts are on-demand audio content that grew enormously in popularity in the 2010s.'),
('technologie', 1, 'Which company makes the Xbox?', 'Microsoft', ARRAY['Sony', 'Nintendo', 'Sega'], 'en', true, 'Microsoft launched the first Xbox in 2001 to compete with PlayStation and Nintendo.'),
('technologie', 1, 'What is YouTube?', 'A video-sharing platform owned by Google', ARRAY['A music streaming service', 'A social media app', 'An email service'], 'en', true, 'YouTube was founded in 2005 and acquired by Google in 2006 for $1.65 billion.'),
('technologie', 1, 'What is the largest online marketplace?', 'Amazon', ARRAY['eBay', 'Alibaba', 'Walmart'], 'en', true, 'Amazon, founded by Jeff Bezos in 1994, is the global leader in e-commerce.'),
('technologie', 1, 'What is RAM in a computer?', 'Random Access Memory - temporary working memory', ARRAY['Read And Memorize', 'Remote Access Module', 'Real Application Memory'], 'en', true, 'RAM stores data that the CPU needs to access quickly while running programs.'),
('technologie', 1, 'What is a laptop?', 'A portable computer', ARRAY['A desktop computer', 'A server', 'A tablet'], 'en', true, 'Laptops combine screen, keyboard, and computing power in a portable form factor.'),
('technologie', 1, 'Which company created the Nintendo Switch?', 'Nintendo', ARRAY['Sony', 'Microsoft', 'Sega'], 'en', true, 'The Nintendo Switch launched in March 2017 and features both portable and TV modes.'),
('technologie', 1, 'What is Spotify?', 'A music streaming service', ARRAY['A video platform', 'A podcast recorder', 'A social network'], 'en', true, 'Spotify was founded in Sweden in 2006 and has over 500 million users.'),
('technologie', 1, 'What is the file extension for a PDF?', '.pdf', ARRAY['.doc', '.txt', '.jpg'], 'en', true, 'PDF stands for Portable Document Format, created by Adobe in 1993.'),
('technologie', 1, 'What is an email?', 'An electronic message sent over the internet', ARRAY['A text message', 'A social media post', 'A phone call'], 'en', true, 'Email (electronic mail) was one of the earliest uses of the internet, dating back to the 1970s.'),
('technologie', 1, 'What does the power button symbol look like?', 'A circle with a line at the top', ARRAY['A triangle', 'A square', 'An arrow'], 'en', true, 'The power symbol combines 0 (off/circle) and 1 (on/line) from binary notation.'),
('technologie', 1, 'What is Google Maps?', 'An online mapping and navigation service', ARRAY['A social media app', 'A search engine', 'A photo editor'], 'en', true, 'Google Maps launched in 2005 and provides maps, directions, and street-level imagery.'),
('technologie', 1, 'Which company makes Galaxy smartphones?', 'Samsung', ARRAY['Apple', 'Huawei', 'Sony'], 'en', true, 'Samsung''s Galaxy series is the main competitor to Apple''s iPhone in the smartphone market.'),
('technologie', 1, 'What is a smartwatch?', 'A wearable computer in the form of a wristwatch', ARRAY['A regular digital watch', 'A fitness band', 'A phone accessory'], 'en', true, 'Smartwatches like Apple Watch and Galaxy Watch offer notifications, health tracking, and apps.'),
('technologie', 1, 'What is the most common video format on the internet?', 'MP4', ARRAY['AVI', 'WMV', 'FLV'], 'en', true, 'MP4 is the most widely used video format online due to its good compression and quality.'),
('technologie', 1, 'What is streaming?', 'Watching or listening to content in real-time without downloading it', ARRAY['Downloading files', 'Compressing data', 'Sharing files'], 'en', true, 'Streaming lets you enjoy music, videos, and games without waiting for a full download.'),
('technologie', 1, 'What is an app?', 'A software application designed for mobile devices', ARRAY['A web browser', 'An operating system', 'A computer hardware part'], 'en', true, 'Apps are downloaded from app stores like the Apple App Store or Google Play Store.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('technologie', 2, 'Who co-founded Apple with Steve Jobs?', 'Steve Wozniak', ARRAY['Bill Gates', 'Tim Cook', 'Elon Musk'], 'en', true, 'Steve Wozniak co-founded Apple in 1976 with Steve Jobs and Ronald Wayne.'),
('technologie', 2, 'In what year was the first iPhone released?', '2007', ARRAY['2005', '2009', '2010'], 'en', true, 'Steve Jobs unveiled the first iPhone on January 9, 2007.'),
('technologie', 2, 'Who invented the World Wide Web?', 'Tim Berners-Lee', ARRAY['Vint Cerf', 'Steve Jobs', 'Bill Gates'], 'en', true, 'Tim Berners-Lee invented the WWW at CERN in 1989.'),
('technologie', 2, 'What is the most used programming language on the web?', 'JavaScript', ARRAY['Python', 'Java', 'C++'], 'en', true, 'JavaScript is essential for front-end web development and increasingly used on the back-end.'),
('technologie', 2, 'What is a VPN?', 'A virtual private network that secures your internet connection', ARRAY['A network virus', 'A type of browser', 'An email protocol'], 'en', true, 'A VPN encrypts internet traffic and masks the user''s IP address for privacy and security.'),
('technologie', 2, 'Who founded Amazon?', 'Jeff Bezos', ARRAY['Elon Musk', 'Mark Zuckerberg', 'Larry Page'], 'en', true, 'Jeff Bezos founded Amazon in 1994 in his garage in Seattle as an online bookstore.'),
('technologie', 2, 'What is 5G?', 'The fifth generation of mobile network technology', ARRAY['A new Wi-Fi standard', 'A communication satellite', 'A Bluetooth protocol'], 'en', true, '5G offers faster speeds and lower latency compared to 4G networks.'),
('technologie', 2, 'What is phishing?', 'An online scam that imitates legitimate websites or emails to steal data', ARRAY['A type of virus', 'A fishing simulation game', 'A network protocol'], 'en', true, 'Phishing aims to steal personal data by impersonating trustworthy entities.'),
('technologie', 2, 'What component mainly determines a computer''s speed?', 'The processor (CPU)', ARRAY['The hard drive', 'The monitor', 'The keyboard'], 'en', true, 'The CPU executes instructions and its speed is measured in GHz.'),
('technologie', 2, 'What is artificial intelligence?', 'Computer systems capable of simulating human intelligence', ARRAY['A physical robot', 'A supercomputer', 'An advanced social network'], 'en', true, 'AI encompasses machine learning, deep learning, and natural language processing.'),
('technologie', 2, 'What image format supports transparency?', 'PNG', ARRAY['JPEG', 'BMP', 'TIFF'], 'en', true, 'PNG format supports transparency (alpha channel), unlike JPEG.'),
('technologie', 2, 'Who founded SpaceX?', 'Elon Musk', ARRAY['Jeff Bezos', 'Richard Branson', 'Bill Gates'], 'en', true, 'SpaceX was founded in 2002 by Elon Musk with the goal of making space travel more affordable.'),
('technologie', 2, 'What is augmented reality (AR)?', 'The overlay of virtual elements on the real world', ARRAY['An entirely virtual world', 'A 3D video game', 'A type of hologram'], 'en', true, 'AR enriches the real-world view with digital information, as seen in Pokemon Go.'),
('technologie', 2, 'What is an SSD?', 'A storage drive with no moving parts, faster than a hard drive', ARRAY['A type of RAM', 'A graphics processor', 'A file format'], 'en', true, 'SSDs (Solid State Drives) use flash memory and offer much faster read/write speeds than HDDs.'),
('technologie', 2, 'What is a deepfake?', 'A video or image falsified using artificial intelligence', ARRAY['An advanced computer virus', 'A type of encryption', 'A video game'], 'en', true, 'Deepfakes use deep learning to create realistic but fake visual content.'),
('technologie', 2, 'What is a cookie in web browsing?', 'A small file stored by the browser to remember user information', ARRAY['A computer virus', 'A type of ad', 'A spyware program'], 'en', true, 'Cookies allow websites to remember preferences, login status, and browsing behavior.'),
('technologie', 2, 'Which company bought WhatsApp in 2014?', 'Facebook (Meta)', ARRAY['Google', 'Microsoft', 'Apple'], 'en', true, 'Facebook acquired WhatsApp for $19 billion in 2014.'),
('technologie', 2, 'What is the name of OpenAI''s chatbot?', 'ChatGPT', ARRAY['Siri', 'Alexa', 'Watson'], 'en', true, 'ChatGPT, launched in November 2022, is based on the GPT language model.'),
('technologie', 2, 'What is an IP address?', 'A numerical identifier assigned to each device connected to the internet', ARRAY['A network password', 'A type of cable', 'An email protocol'], 'en', true, 'IP addresses allow devices to be identified and located on a network.'),
('technologie', 2, 'What is Wikipedia?', 'A free, collaborative online encyclopedia', ARRAY['A search engine', 'A news website', 'A social media platform'], 'en', true, 'Wikipedia, founded in 2001, is written by volunteers worldwide in hundreds of languages.'),
('technologie', 2, 'Who invented the telephone?', 'Alexander Graham Bell', ARRAY['Thomas Edison', 'Nikola Tesla', 'Guglielmo Marconi'], 'en', true, 'Alexander Graham Bell patented the telephone in 1876.'),
('technologie', 2, 'What is responsive design?', 'Website design that adapts to all screen sizes', ARRAY['A programming language', 'A design software', 'An image format'], 'en', true, 'Responsive design uses CSS techniques to adapt layouts for phones, tablets, and desktops.'),
('technologie', 2, 'What is the role of an antivirus?', 'To detect and remove malicious software', ARRAY['To speed up the computer', 'To block ads', 'To back up data'], 'en', true, 'Antivirus software protects devices against viruses, malware, ransomware, and other threats.'),
('technologie', 2, 'Which platform is used for sharing source code?', 'GitHub', ARRAY['LinkedIn', 'Dropbox', 'Google Drive'], 'en', true, 'GitHub, acquired by Microsoft in 2018, is the largest collaborative development platform.'),
('technologie', 2, 'What is a drone?', 'An unmanned aircraft, remote-controlled or autonomous', ARRAY['A ground robot', 'A miniature satellite', 'A type of camera'], 'en', true, 'Drones are used for aerial photography, delivery, agriculture, and surveillance.'),
('technologie', 2, 'What is an algorithm?', 'A set of instructions to solve a problem', ARRAY['A type of virus', 'A programming language', 'A hardware component'], 'en', true, 'Algorithms are the foundation of programming and data processing.'),
('technologie', 2, 'What is the role of a firewall?', 'To protect a network against unauthorized access', ARRAY['To speed up internet', 'To store data', 'To cool the computer'], 'en', true, 'Firewalls filter incoming and outgoing network traffic based on security rules.'),
('technologie', 2, 'What is the Dark Web?', 'A part of the internet not indexed by search engines, accessible via special software', ARRAY['A website in dark mode', 'A secret social network', 'A type of virus'], 'en', true, 'The Dark Web requires special browsers like Tor and hosts both legal and illegal activities.'),
('technologie', 2, 'What programming language was created by Guido van Rossum?', 'Python', ARRAY['Java', 'Ruby', 'Swift'], 'en', true, 'Python, created in 1991, is one of the most popular languages due to its simplicity.'),
('technologie', 2, 'What is wireless charging based on?', 'Electromagnetic induction (Qi standard)', ARRAY['Bluetooth technology', 'NFC signals', 'Infrared beams'], 'en', true, 'The Qi standard uses electromagnetic induction to transfer energy without physical contact.'),
('technologie', 2, 'Which company launched the Echo smart speakers?', 'Amazon', ARRAY['Google', 'Apple', 'Samsung'], 'en', true, 'Amazon launched the Echo speaker with Alexa assistant in 2014.'),
('technologie', 2, 'What is Google''s cloud computing platform called?', 'Google Cloud Platform (GCP)', ARRAY['AWS', 'Azure', 'IBM Cloud'], 'en', true, 'GCP competes with AWS and Microsoft Azure in the cloud computing market.'),
('technologie', 2, 'What is the name of Apple''s custom processor series?', 'Apple Silicon (M-series)', ARRAY['Intel Core', 'AMD Ryzen', 'Snapdragon'], 'en', true, 'Apple launched its M1 chip in 2020, replacing Intel processors in Mac computers.'),
('technologie', 2, 'What is a firewall?', 'Software or hardware that monitors and controls network traffic', ARRAY['A physical wall around servers', 'An antivirus program', 'A backup system'], 'en', true, 'Firewalls act as gatekeepers, filtering traffic based on predefined security rules.'),
('technologie', 2, 'What is virtual reality (VR)?', 'A fully simulated computer environment the user is immersed in', ARRAY['An advanced photo filter', 'A 3D movie', 'A hologram display'], 'en', true, 'VR uses headsets to immerse users in interactive digital worlds.'),
('technologie', 2, 'In what year was Google founded?', '1998', ARRAY['1996', '2000', '2002'], 'en', true, 'Google was founded in 1998 by Larry Page and Sergey Brin at Stanford University.'),
('technologie', 2, 'What is Instagram?', 'A photo and video sharing social media platform', ARRAY['A messaging app', 'A search engine', 'A music streaming service'], 'en', true, 'Instagram, launched in 2010 and acquired by Facebook in 2012, has over 2 billion users.'),
('technologie', 2, 'What does MS-DOS stand for?', 'Microsoft Disk Operating System', ARRAY['Multi System Data Operating Software', 'Main Server Digital OS', 'Micro Soft Desktop OS'], 'en', true, 'MS-DOS was the dominant PC operating system in the 1980s before Windows.'),
('technologie', 2, 'What is LinkedIn?', 'A professional social networking platform', ARRAY['A job search website only', 'A freelancing platform', 'A business email service'], 'en', true, 'LinkedIn, founded in 2003 and acquired by Microsoft in 2016, connects professionals worldwide.'),
('technologie', 2, 'What is a hashtag used for on social media?', 'To categorize content and make it discoverable', ARRAY['To tag friends', 'To encrypt messages', 'To create links'], 'en', true, 'Hashtags allow users to find and follow topics across social media platforms.'),
('technologie', 2, 'What company developed the first commercially successful smartphone before iPhone?', 'BlackBerry (Research In Motion)', ARRAY['Nokia', 'Motorola', 'Palm'], 'en', true, 'BlackBerry dominated the business smartphone market in the early 2000s with its QWERTY keyboard.'),
('technologie', 2, 'What is the Internet of Things (IoT)?', 'The network of physical objects connected to the internet', ARRAY['A new type of internet', 'A social network for devices', 'A security protocol'], 'en', true, 'IoT connects everyday objects like thermostats, watches, and appliances to the internet.'),
('technologie', 2, 'What is a browser extension?', 'A small software module that adds features to a web browser', ARRAY['A separate web browser', 'A type of programming language', 'An internet protocol'], 'en', true, 'Browser extensions customize the browsing experience with tools like ad blockers and password managers.'),
('technologie', 2, 'What is two-factor authentication (2FA)?', 'A security method requiring two different forms of identity verification', ARRAY['Using two passwords', 'Having two accounts', 'An advanced antivirus'], 'en', true, '2FA typically combines a password with a code sent via SMS or generated by an authenticator app.'),
('technologie', 2, 'What is the name of Google''s AI assistant?', 'Google Assistant', ARRAY['Siri', 'Alexa', 'Cortana'], 'en', true, 'Google Assistant is available on smartphones, smart speakers, and other Google devices.');
